import sys
import re
import json
import operator
import ast

def evaluate_expression(expr, variables):
    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id not in variables:
                raise ValueError(f"Undefined variable: {node.id}")
            return variables[node.id]
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_map = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.FloorDiv: operator.floordiv,
                ast.Mod: operator.mod,
                ast.Pow: operator.pow,
                ast.USub: operator.neg,
                ast.UAdd: operator.pos
            }
            if type(node.op) not in op_map:
                raise ValueError(f"Unsupported operation: {type(node.op)}")
            return op_map[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_map = {
                ast.USub: operator.neg,
                ast.UAdd: operator.pos
            }
            if type(node.op) not in op_map:
                raise ValueError(f"Unsupported operation: {type(node.op)}")
            return op_map[type(node.op)](operand)
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    tree = ast.parse(expr, mode='eval')
    return eval_node(tree.body)

def main():
    if len(sys.argv) != 2:
        print("Usage: python extract.py <path>")
        sys.exit(1)

    path = sys.argv[1]
    variables = {}

    try:
        with open(path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()
                if not line:
                    continue

                match = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', line)
                if not match:
                    continue

                key, expr = match.groups()
                if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', key):
                    continue

                try:
                    value = evaluate_expression(expr, variables)
                    variables[key] = value
                except Exception as e:
                    print(f"Error evaluating expression '{expr}': {e}", file=sys.stderr)
    except FileNotFoundError:
        print(f"File not found: {path}", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f"Permission denied: {path}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)

    print(json.dumps(variables))

if __name__ == "__main__":
    main()

import sys
import os
import json
import secrets
import string
import time
import hashlib
from pathlib import Path

def generate_token():
    return ''.join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))

def compute_key(token):
    return hashlib.sha256(token.encode()).hexdigest()

def load_tokens():
    tokens_path = Path('tokens.json')
    if not tokens_path.exists():
        return {}
    with tokens_path.open('r') as f:
        return json.load(f)

def save_tokens(tokens):
    tokens_path = Path('tokens.json')
    with tokens_path.open('w') as f:
        json.dump(tokens, f)

def issue(email):
    if not isinstance(email, str) or '@' not in email:
        print('Invalid email format.')
        return
    tokens = load_tokens()
    token = generate_token()
    key = compute_key(token)
    while key in tokens:
        token = generate_token()
        key = compute_key(token)
    tokens[key] = {'email': email, 'expires_at': int(time.time()) + 3600}
    save_tokens(tokens)
    print(token)

def verify(token):
    if not isinstance(token, str) or len(token) != 32 or not token.isalnum():
        print('Invalid token format.')
        return
    tokens = load_tokens()
    key = compute_key(token)
    if key in tokens and tokens[key]['expires_at'] > int(time.time()):
        email = tokens[key]['email']
        del tokens[key]
        save_tokens(tokens)
        print(email)
    else:
        print('invalid')

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python reset_tool.py [issue|verify] [EMAIL|TOKEN]')
        sys.exit(1)

    command, arg = sys.argv[1], sys.argv[2]
    if command == 'issue':
        issue(arg)
    elif command == 'verify':
        verify(arg)
    else:
        print('Invalid command. Use "issue" or "verify".')
        sys.exit(1)

import sys
import html
import os

def read_stdin():
    return sys.stdin.read().strip().split('\n')

def read_template():
    template_path = os.path.join(os.getcwd(), 'invoice_template.html')
    if not os.path.isfile(template_path):
        raise FileNotFoundError("Template file not found.")
    with open(template_path, 'r') as file:
        return file.read()

def escape_html(text):
    return html.escape(text)

def render_invoice(invoice_number, items):
    template = read_template()
    item_rows = '\n'.join([f'<tr><td>{escape_html(item)}</td></tr>' for item in items])
    return template.replace('{{invoice_number}}', escape_html(invoice_number)).replace('{{item_rows}}', item_rows)

def main():
    try:
        lines = read_stdin()
        if not lines:
            raise ValueError("No input provided.")
        invoice_number = lines[0]
        items = lines[1:]
        rendered_html = render_invoice(invoice_number, items)
        print(rendered_html)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

