def main():
    if len(sys.argv) != 3:
        print("Usage: python throttled_runner.py <rate_per_second> <jobs_file>")
        return

    try:
        rate_per_second = float(sys.argv[1])
        if rate_per_second <= 0:
            raise ValueError
    except ValueError:
        print("Error: rate_per_second must be a positive number.")
        return

    jobs_file = sys.argv[2]

    # Validate file path
    if not os.path.isfile(jobs_file):
        print("Error: jobs_file not found.")
        return

