import shlex

def load_cache():
    cache_file = '.cmd_cache'
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    with open('.cmd_cache', 'w') as f:
        json.dump(cache, f)

def validate_command(command):
    # Basic validation to prevent path traversal and command injection
    if not command.isidentifier():
        raise ValueError("Invalid command name")

def main():
    cache = load_cache()
    if len(sys.argv) < 2:
        sys.exit(1)

    command = sys.argv[1]
    args = sys.argv[2:]

    try:
        validate_command(command)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    command_args = (command,) + tuple(args)
    command_key = json.dumps(command_args)

    if command_key in cache:
        print(cache[command_key])
        sys.exit(0)

    try:
