        result = subprocess.run(shlex.split(command) + args, capture_output=True, text=True, check=True)
        print(result.stdout)
        cache[command_key] = result.stdout
        save_cache(cache)
        sys.exit(0)
    except subprocess.CalledProcessError as e:
        sys.exit(e.returncode)
    except FileNotFoundError:
        print(f"Error: Command '{command}' not found", file=sys.stderr)
        sys.exit(127)
