import sys
import json
import subprocess
import shlex
from concurrent.futures import ThreadPoolExecutor, as_completed

def validate_config(config):
    if not isinstance(config, dict):
        raise ValueError("Configuration must be a JSON object.")
    if 'max_parallel' not in config or not isinstance(config['max_parallel'], int):
        raise ValueError("Configuration must contain 'max_parallel' as an integer.")
    if 'tasks' not in config or not isinstance(config['tasks'], list):
        raise ValueError("Configuration must contain 'tasks' as a list.")
    for task in config['tasks']:
        if not isinstance(task, dict) or 'id' not in task or 'command' not in task:
            raise ValueError("Each task must be a dictionary with 'id' and 'command'.")

def run_task(task):
    task_id = task['id']
    command = task['command']
    try:
        # Use shlex.split to safely split the command string
        args = shlex.split(command)
        result = subprocess.run(args, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return task_id, "ok"
    except subprocess.CalledProcessError as e:
        return task_id, "error"
    except Exception as e:
        return task_id, f"error: {str(e)}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python runner.py CONFIG.json")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
        validate_config(config)
    except (json.JSONDecodeError, FileNotFoundError, ValueError) as e:
        print(f"Error reading or parsing config: {e}")
        sys.exit(1)

    max_parallel = config['max_parallel']
    tasks = config['tasks']

    results = {}
    with ThreadPoolExecutor(max_workers=max_parallel) as executor:
        future_to_task = {executor.submit(run_task, task): task for task in tasks}
        for future in as_completed(future_to_task):
            task_id, status = future.result()
            results[task_id] = status

    print(json.dumps(results))

if __name__ == "__main__":
    main()

import sys
import re
import os

def load_expenses():
    try:
        with open('expenses.state', 'r') as file:
            return [line.strip() for line in file.readlines()]
    except FileNotFoundError:
        return []
    except IOError as e:
        print(f"Error reading expenses.state: {e}", file=sys.stderr)
        sys.exit(1)

def save_expenses(expenses):
    try:
        with open('expenses.state', 'w') as file:
            for expense in expenses:
                file.write(expense + '\n')
    except IOError as e:
        print(f"Error writing to expenses.state: {e}", file=sys.stderr)
        sys.exit(1)

def validate_amount(amount):
    return re.match(r'^\d+(\.\d{2})?$', amount) is not None

def validate_category(category):
    return re.match(r'^[^\s]+$', category) is not None

def main():
    expenses = load_expenses()
    for line in sys.stdin:
        line = line.strip()
        if line.startswith('add '):
            parts = line.split(maxsplit=2)
            if len(parts) == 3:
                _, amount, category = parts
                if validate_amount(amount) and validate_category(category):
                    expenses.append(f"{amount} {category}")
                    save_expenses(expenses)
        elif line == 'list':
            for expense in expenses:
                print(expense)
        else:
            print(f"Invalid command: {line}", file=sys.stderr)

