        if not normalized_path.startswith(os.path.normpath(authorized_base)):
            print("Denied")
            sys.exit(0)

        if not os.path.isfile(normalized_path):
            print("Denied")
            sys.exit(0)

        with open(normalized_path, 'rb') as file:
            while True:
                chunk = file.read(4096)
                if not chunk:
                    break
