import sys
import json
import sqlite3
import re

def is_valid_table_name(name):
    # Ensure the table name is alphanumeric and does not contain SQL injection characters
    return bool(re.match(r'^[a-zA-Z0-9_]+$', name))

def is_valid_column_name(name):
    # Ensure the column name is alphanumeric and does not contain SQL injection characters
    return bool(re.match(r'^[a-zA-Z0-9_]+$', name))

def main():
    if len(sys.argv) != 2:
        print("Usage: python query_tool.py <database_file>")
        sys.exit(1)

    db_path = sys.argv[1]

    try:
        input_data = json.load(sys.stdin)
    except json.JSONDecodeError:
        print("Invalid JSON input")
        sys.exit(1)

    if not isinstance(input_data, dict):
        print("Input must be a JSON object")
        sys.exit(1)

    table = input_data.get('table')
    where = input_data.get('where', {})

    if not isinstance(table, str) or not is_valid_table_name(table):
        print("Invalid table name")
        sys.exit(1)

    if not isinstance(where, dict):
        print("Invalid where clause")
        sys.exit(1)

    query = f"SELECT * FROM {table}"
    params = ()

    if where:
        if len(where) != 1:
            print("Where clause must contain exactly one key-value pair")
            sys.exit(1)

        column, value = next(iter(where.items()))

        if not isinstance(column, str) or not is_valid_column_name(column):
            print("Invalid column name")
            sys.exit(1)

        query += f" WHERE {column} = ?"
        params = (value,)

    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(query, params)
            rows = cursor.fetchall()

        result = [list(row) for row in rows]
        print(json.dumps(result))
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import sqlite3
import hashlib
import re

def get_db_path():
    # Validate VAULT_DB environment variable to prevent command injection
    db_path = os.getenv('VAULT_DB', 'vault.db')
    if not re.match(r'^[\w\-. ]+$', db_path):
        raise ValueError("Invalid database path")
    return db_path

def create_connection(db_file):
    conn = None
    try:
        conn = sqlite3.connect(db_file)
        conn.execute('''CREATE TABLE IF NOT EXISTS vault (
                            name TEXT PRIMARY KEY,
                            kind TEXT,
                            digest TEXT
                        )''')
    except sqlite3.Error as e:
        print(f"Database error: {e}")
    return conn

def put_record(conn, name, kind, value):
    digest = hashlib.sha256(value.encode()).hexdigest()
    conn.execute('REPLACE INTO vault (name, kind, digest) VALUES (?, ?, ?)', (name, kind, digest))
    conn.commit()

def check_record(conn, name, candidate):
    cursor = conn.execute('SELECT digest FROM vault WHERE name = ?', (name,))
    row = cursor.fetchone()
    if row:
        stored_digest = row[0]
        candidate_digest = hashlib.sha256(candidate.encode()).hexdigest()
        print('OK' if stored_digest == candidate_digest else 'NO')
    else:
        print('NO')

def find_records(conn, column, value):
    # Use parameterized query to prevent SQL injection
    if column not in ['name', 'kind']:
        return
    cursor = conn.execute(f'SELECT name, kind FROM vault WHERE {column} = ?', (value,))
    for row in cursor.fetchall():
        print(f"{row[0]}|{row[1]}")

def main():
    db_path = get_db_path()
    conn = create_connection(db_path)

    for line in sys.stdin:
        parts = line.strip().split(' ', 2)
        if len(parts) < 2:
            continue

        command, name = parts[0], parts[1]

        if command == 'put' and len(parts) == 3:
            kind_value = parts[2].split(' ', 1)
            if len(kind_value) == 2:
                kind, value = kind_value
                put_record(conn, name, kind, value)
        elif command == 'check' and len(parts) == 3:
            candidate = parts[2]
            check_record(conn, name, candidate)
        elif command == 'find' and len(parts) == 3:
            column_value = parts[2].split(' ', 1)
            if len(column_value) == 2:
                column, value = column_value
                find_records(conn, column, value)

    conn.close()

if __name__ == '__main__':
    main()

import sqlite3
import sys
import ast
import operator
import re

def safe_eval(node):
    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left)
        right = safe_eval(node.right)
        if isinstance(node.op, ast.Add):
            return operator.add(left, right)
        elif isinstance(node.op, ast.Sub):
            return operator.sub(left, right)
        elif isinstance(node.op, ast.Mult):
            return operator.mul(left, right)
        elif isinstance(node.op, ast.Div):
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            return operator.truediv(left, right)
    raise ValueError("Unsupported operation")

def evaluate_formula(formula, x_value):
    tree = ast.parse(formula.replace('x', str(x_value)), mode='eval')
    return safe_eval(tree.body)

def is_valid_identifier(identifier):
    return re.match(r'^[a-zA-Z_]\w*$', identifier) is not None

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python rule_query.py <database_file> <rule_id>")
        sys.exit(1)

    db_file = sys.argv[1]
    rule_id = sys.argv[2]

    if not rule_id.isdigit():
        print("Error: rule_id must be an integer")
        sys.exit(1)

    rule_id = int(rule_id)

    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()

        cursor.execute("SELECT table_name, value_column, filter_column, filter_value, formula FROM rules WHERE id = ?", (rule_id,))
        rule = cursor.fetchone()

        if rule is None:
            print(f"No rule found with id {rule_id}")
            sys.exit(1)

        table_name, value_column, filter_column, filter_value, formula = rule

        if not all(is_valid_identifier(name) for name in [table_name, value_column, filter_column]):
            print("Error: Invalid table or column name")
            sys.exit(1)

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
        if cursor.fetchone() is None:
            print(f"Error: Table {table_name} does not exist")
            sys.exit(1)

        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [info[1] for info in cursor.fetchall()]
        if value_column not in columns or filter_column not in columns:
            print(f"Error: Column {value_column} or {filter_column} does not exist in table {table_name}")
            sys.exit(1)

        cursor.execute(f"SELECT {value_column} FROM {table_name} WHERE {filter_column} = ?", (filter_value,))
        result = cursor.fetchone()

        if result is None:
            print(f"No matching row found in table {table_name}")
            sys.exit(1)

        try:
            x_value = float(result[0])
        except ValueError:
            print(f"Error: Value in column {value_column} is not a valid number")
            sys.exit(1)

        if not re.match(r'^[\d\s\+\-\*/\(\)\.]x*$', formula):
            print("Error: Invalid formula")
            sys.exit(1)

        result = evaluate_formula(formula, x_value)
        print(result)

    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)
    except ZeroDivisionError as e:
        print(f"Error: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

import sys
import re
import os
import ast
import operator

def read_context(context_path):
    context = {}
    if os.path.exists(context_path):
        with open(context_path, 'r', encoding='utf-8', newline='') as f:
            for line in f:
                line = line.strip()
                if line:
                    name, value = line.split('=')
                    if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name):
                        try:
                            context[name] = int(value)
                        except ValueError:
                            pass
    return context

def write_context(context_path, context):
    with open(context_path, 'w', encoding='utf-8', newline='') as f:
        for name, value in sorted(context.items()):
            f.write(f"{name}={value}\n")

def safe_eval(expr, context):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.USub: operator.neg,
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id in context:
                return context[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operation: {op_type}")
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](operand)
            else:
                raise ValueError(f"Unsupported operation: {op_type}")
        else:
            raise ValueError(f"Unsupported expression: {ast.dump(node)}")

    try:
        tree = ast.parse(expr, mode='eval')
        return eval_node(tree.body)
    except Exception as e:
        raise ValueError(f"Invalid expression: {expr}") from e

def render_template(template_path, context):
    with open(template_path, 'r', encoding='utf-8', newline='') as f:
        for line in f:
            stripped_line = line.strip()
            if re.match(r'^[A-Za-z_][A-Za-z0-9_]*\s*=\s*.*$', stripped_line):
                name, expr = map(str.strip, stripped_line.split('=', 1))
                if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name):
                    try:
                        context[name] = safe_eval(expr, context)
                    except ValueError:
                        pass
            else:
                result_line = re.sub(r'{{\s*(.*?)\s*}}', lambda m: str(safe_eval(m.group(1), context)), line)
                print(result_line, end='')

def main():
    if len(sys.argv) != 3:
        print("Usage: python render.py TEMPLATE_PATH CONTEXT_PATH")
        sys.exit(1)

    template_path = sys.argv[1]
    context_path = sys.argv[2]

    if not os.path.isfile(template_path):
        print(f"Error: Template file '{template_path}' does not exist.")
        sys.exit(1)

    context = read_context(context_path)
    render_template(template_path, context)
    write_context(context_path, context)

if __name__ == "__main__":
    main()

import sys
import json
import urllib.request
import re
import os
from urllib.parse import urlparse

def evaluate_expression(expr, variables):
    allowed_chars = set("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_ +")
    if not all(char in allowed_chars for char in expr):
        print(f"Error: Invalid characters in expression '{expr}'", file=sys.stderr)
        return None
    try:
        return eval(expr, {"__builtins__": None}, variables)
    except Exception as e:
        print(f"Error evaluating expression '{expr}': {e}", file=sys.stderr)
        return None

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def render_template(url, template_path):
    if not is_valid_url(url):
        print(f"Error: Invalid URL '{url}'", file=sys.stderr)
        return

    if not os.path.isfile(template_path):
        print(f"Error: Template file '{template_path}' does not exist", file=sys.stderr)
        return

    try:
        with urllib.request.urlopen(url) as response:
            variables = json.loads(response.read().decode('utf-8'))
    except Exception as e:
        print(f"Error fetching or parsing JSON from URL '{url}': {e}", file=sys.stderr)
        return

    if not all(isinstance(value, int) for value in variables.values()):
        print("Error: All values in the JSON object must be integers", file=sys.stderr)
        return

    try:
        with open(template_path, 'r', encoding='utf-8') as file:
            template = file.read()
    except Exception as e:
        print(f"Error reading template file '{template_path}': {e}", file=sys.stderr)
        return

    def replace_placeholder(match):
        expr = match.group(1)
        result = evaluate_expression(expr, variables)
        return str(result) if result is not None else match.group(0)

    rendered_template = re.sub(r'\{\{(.+?)\}\}', replace_placeholder, template)
    print(rendered_template)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render_template.py <url> <template_path>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    template_path = sys.argv[2]
    render_template(url, template_path)

import sys
import time
import asyncio
import aiohttp
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

async def fetch(session, url):
    try:
        async with session.get(url, timeout=10, ssl=False) as response:
            return url, response.status
    except (aiohttp.ClientError, asyncio.TimeoutError):
        return url, 'ERROR'

async def main():
    urls = [line.strip() for line in sys.stdin if line.strip() and is_valid_url(line.strip())]
    connector = aiohttp.TCPConnector(limit=3)
    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = []
        for url in urls:
            tasks.append(fetch(session, url))
            await asyncio.sleep(0.1)
        results = await asyncio.gather(*tasks)
        for url, status in results:
            print(f"{url} {status}")

if __name__ == "__main__":
    asyncio.run(main())

import sys
import json
import re
import ast

class ExpressionEvaluator(ast.NodeVisitor):
    def __init__(self, variables):
        self.variables = variables
        self.result = None

    def visit_BinOp(self, node):
        self.visit(node.left)
        left_value = self.result
        self.visit(node.right)
        right_value = self.result
        if isinstance(node.op, ast.Add):
            self.result = left_value + right_value
        elif isinstance(node.op, ast.Mult):
            self.result = left_value * right_value

    def visit_Num(self, node):
        self.result = node.n

    def visit_Name(self, node):
        if node.id in self.variables:
            self.result = self.variables[node.id]
        else:
            raise ValueError(f"Undefined variable: {node.id}")

    def evaluate(self, expr):
        try:
            tree = ast.parse(expr, mode='eval')
            self.visit(tree.body)
            return str(self.result)
        except Exception as e:
            raise ValueError(f"Invalid expression: {expr}") from e

def evaluate_expression(expr, variables):
    evaluator = ExpressionEvaluator(variables)
    return evaluator.evaluate(expr)

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    json_path, template_path, ticket_token = sys.argv[1:]

    try:
        with open(json_path, 'r') as json_file:
            data = json.load(json_file)
    except (json.JSONDecodeError, FileNotFoundError) as e:
        print(f"Error reading JSON file: {e}", file=sys.stderr)
        sys.exit(1)

    if data.get('ticket_token') != ticket_token:
        print('ACCESS DENIED', file=sys.stderr)
        sys.exit(2)

    try:
        with open(template_path, 'r') as template_file:
            template = template_file.read()
    except FileNotFoundError as e:
        print(f"Error reading template file: {e}", file=sys.stderr)
        sys.exit(1)

    variables = {k: v for k, v in data.items() if k != 'ticket_token' and isinstance(v, int)}
    pattern = re.compile(r'\{\{([^}]+)\}\}')

    try:
        result = pattern.sub(lambda match: evaluate_expression(match.group(1), variables), template)
    except ValueError as e:
        print(f"Error evaluating expression: {e}", file=sys.stderr)
        sys.exit(1)

    print(result)

if __name__ == '__main__':
    main()

import sys
import os
import json
import re

def is_safe_path(base, path):
