    return os.path.abspath(path).startswith(os.path.abspath(base))

def main():
    if len(sys.argv) != 2:
        print("Usage: python job_runner.py <config_path>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (IOError, json.JSONDecodeError) as e:
        print(f"config_error: {str(e)}", file=sys.stderr)
        sys.exit(2)

    if not isinstance(config, dict) or 'tokens' not in config or 'jobs' not in config:
        print("config_error: Invalid configuration structure", file=sys.stderr)
        sys.exit(2)

    tokens = config['tokens']
    jobs = config['jobs']
    token_dir = os.getenv('TOKEN_DIR')

    if not token_dir:
        print("config_error: TOKEN_DIR environment variable is not set", file=sys.stderr)
        sys.exit(2)

    try:
        with open('run.log', 'w') as log_file:
            for job in jobs:
                if not isinstance(job, dict) or not all(k in job for k in ('name', 'token', 'role')):
                    continue

                job_name = job['name']
                job_token = job['token']
                job_role = job['role']

                if not all(isinstance(x, str) for x in [job_name, job_token, job_role]):
                    continue

                token_path = os.path.join(token_dir, job_token)
                if not is_safe_path(token_dir, token_path):
