                        token_value = token_file.readline().strip()
                except IOError:
                    token_value = None

                allowed = token_value in tokens and job_role == "runner"
                log_entry = json.dumps({'job': job_name, 'allowed': allowed})
                log_file.write(log_entry + '\n')
