    main()

import sys
import os
import json
import time
import hmac
import hashlib
import base64
import re

SECRET_KEY = b'supersecretkey'  # This should be securely stored and not hardcoded

def load_json(file_path):
    if not os.path.exists(file_path):
        return {}
    with open(file_path, 'r') as f:
        return json.load(f)

def save_json(file_path, data):
    with open(file_path, 'w') as f:
        json.dump(data, f)

def sanitize_input(input_str):
    return re.sub(r'[^\w\-]', '', input_str)

def generate_token(client_id, issue_time):
    message = f"{client_id}:{issue_time}".encode()
    signature = hmac.new(SECRET_KEY, message, hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(message + signature).decode()
    return token

def verify_token(token):
    try:
        decoded = base64.urlsafe_b64decode(token.encode())
        message, signature = decoded[:-32], decoded[-32:]
        expected_signature = hmac.new(SECRET_KEY, message, hashlib.sha256).digest()
        if not hmac.compare_digest(signature, expected_signature):
            return None, None
        client_id, issue_time = message.decode().split(':')
        return client_id, int(issue_time)
    except Exception:
        return None, None

def issue():
    client_id = sanitize_input(sys.stdin.readline().strip())
    secret = sys.stdin.readline().strip()

    client_config = load_json('client_config.json')
    usage = load_json('usage.json')

    if client_id not in client_config or client_config[client_id]['secret'] != secret:
        sys.stderr.write('unknown client or secret\n')
        sys.exit(1)

    now = int(time.time())
    quota = client_config[client_id]['quota_per_minute']
    recent_usage = [s for s in usage.get(client_id, []) if now - 60 <= s <= now]

    if len(recent_usage) >= quota:
        sys.stderr.write('quota exceeded\n')
        sys.exit(2)

    recent_usage.append(now)
    usage[client_id] = recent_usage
    save_json('usage.json', usage)

    token = generate_token(client_id, now)
    print(token)

def verify():
    token = sys.stdin.readline().strip()

    client_id, issue_time = verify_token(token)
    if client_id is None or issue_time is None:
        sys.stderr.write('invalid token\n')
        sys.exit(1)

    now = int(time.time())
    if now < issue_time + 300:
        expires_at = issue_time + 300
        print(f"{client_id} {expires_at}")
    else:
        sys.stderr.write('invalid token\n')
        sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) != 2 or sys.argv[1] not in ['issue', 'verify']:
        sys.exit(1)

    if sys.argv[1] == 'issue':
        issue()
    else:
        verify()

import sys
import xml.etree.ElementTree as ET
import subprocess
from concurrent.futures import ThreadPoolExecutor
import os
import re

def sanitize_command(command):
    # Allow only alphanumeric characters, spaces, and basic shell operators
    return re.sub(r'[^a-zA-Z0-9\s\.\-_\/\:\(\)]', '', command)

def run_command(pool_name, command):
    try:
        sanitized_command = sanitize_command(command)
        result = subprocess.run(sanitized_command, shell=False, capture_output=True, text=True)
        for line in result.stdout.splitlines():
            print(f"{pool_name}\t{line}")
    except subprocess.CalledProcessError as e:
        print(f"{pool_name}\tError executing command: {e}", file=sys.stderr)
    except Exception as e:
        print(f"{pool_name}\tUnexpected error: {e}", file=sys.stderr)

def parse_xml_safe(file_path):
    # Prevent XXE by disabling external entity loading
    parser = ET.XMLParser(resolve_entities=False)
    return ET.parse(file_path, parser=parser)

def main(config_path):
    if not os.path.isfile(config_path):
        print("Error: Configuration file does not exist.", file=sys.stderr)
        sys.exit(1)

    try:
        tree = parse_xml_safe(config_path)
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    root = tree.getroot()

    pool_configs = {}
    for pool in root.findall('pool'):
        name = pool.get('name')
        limit = int(pool.get('limit'))
        commands = [cmd.text for cmd in pool.findall('command')]
        pool_configs[name] = (limit, commands)

    for line in sys.stdin:
        pool_name = line.strip()
        if pool_name in pool_configs:
            limit, commands = pool_configs[pool_name]
            with ThreadPoolExecutor(max_workers=limit) as executor:
                executor.map(lambda cmd: run_command(pool_name, cmd), commands)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python pool_runner.py <config_file>")
        sys.exit(1)
    main(sys.argv[1])

import sys
import os
import hashlib
import re

def compute_tag(value, secret):
    return hashlib.sha256(f"{value}{secret}".encode()).hexdigest()[:16]

def is_valid_expression(expression):
    # Allow only decimal integers, +, -, *, (, ), and spaces
    return re.fullmatch(r'[0-9+\-*\(\) ]+', expression) is not None

def evaluate_safe_expression(expression):
    # Evaluate the expression safely using a restricted set of operations
    allowed_names = {
        '__builtins__': None,
    }
    return eval(expression, {"__builtins__": None}, allowed_names)

def main():
    secret = os.getenv('RENDERER_KEY')
    if not secret:
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if not is_valid_expression(line):
            continue
        try:
            value = evaluate_safe_expression(line)
            if isinstance(value, int):
                tag = compute_tag(value, secret)
                print(f"{value}|{tag}")
        except Exception:
            continue

if __name__ == "__main__":
    main()

import os
import hashlib
import re

def sanitize_path(path):
    # Normalize the path to prevent path traversal
    return os.path.normpath(path)

def compute_file_digest(file_path):
    # Use a buffer to read large files in chunks
    hash_obj = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()
    except IOError:
        return None

def is_valid_path(path):
    # Ensure the path is within the expected directory
    return os.path.abspath(path).startswith(os.getcwd())

def main():
    with open('input_paths.txt', 'r') as input_file, open('digest.log', 'w') as log_file:
        processed = 0
        errors = 0

        for line in input_file:
            path = line.strip()
            sanitized_path = sanitize_path(path)

            if not is_valid_path(sanitized_path):
                log_file.write(f"ERROR {path}\n")
                errors += 1
                continue

            if os.path.isfile(sanitized_path):
                digest = compute_file_digest(sanitized_path)
                if digest:
                    log_file.write(f"{path}\t{digest}\n")
                    processed += 1
                else:
                    log_file.write(f"ERROR {path}\n")
                    errors += 1
            else:
                log_file.write(f"ERROR {path}\n")
                errors += 1

        log_file.write(f"Completed: {processed} processed, {errors} errors\n")

if __name__ == "__main__":
    main()

