    except Exception:
        return 0

async def fetch_all_statuses(urls, max_concurrent):
    connector = aiohttp.TCPConnector(limit=max_concurrent)
    async with ClientSession(connector=connector) as session:
        tasks = []
        for url in urls:
            task = asyncio.create_task(fetch_status(session, url))
            tasks.append(task)
            await asyncio.sleep(0.2)
        return await asyncio.gather(*tasks)

def sanitize_html(text):
    return re.sub(r'[<>]', '', text)

def main():
    if len(sys.argv) != 4:
        print("Usage: python build_report.py data.json template.html report.html")
        sys.exit(1)

    json_path, template_path, output_path = sys.argv[1:]

    try:
        with open(json_path, 'r') as json_file:
            data = json.load(json_file)
    except (json.JSONDecodeError, FileNotFoundError, IOError):
        print("Error reading or parsing JSON file.")
        sys.exit(1)

    if not isinstance(data.get('max_concurrent'), int) or data['max_concurrent'] <= 0:
        print("Invalid max_concurrent value.")
        sys.exit(1)

    urls = data.get('urls', [])
    if not isinstance(urls, list) or not all(isinstance(url, str) and validate_url(url) for url in urls):
        print("Invalid or missing URLs.")
        sys.exit(1)

    try:
        statuses = asyncio.run(fetch_all_statuses(urls, data['max_concurrent']))
    except Exception as e:
        print(f"Error fetching statuses: {e}")
        sys.exit(1)

    try:
        with open(template_path, 'r') as template_file:
            template = template_file.read()
    except FileNotFoundError:
        print("Template file not found.")
        sys.exit(1)

    rows = ''.join(f'<tr><td>{sanitize_html(url)}</td><td>{status}</td></tr>' for url, status in zip(urls, statuses))
    output_html = template.replace('{{rows}}', rows)

    try:
        with open(output_path, 'w') as output_file:
            output_file.write(output_html)
    except IOError:
        print("Error writing output file.")
        sys.exit(1)

    print(len(urls))

if __name__ == '__main__':
    main()

import sys
import json
import re
import ast
import operator

# Supported operators
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.USub: operator.neg,
    ast.BinOp: lambda x, y: None,  # Placeholder for binary operations
}

def evaluate_expression(expression, variables):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')
        return eval_node(tree.body, variables)
    except (SyntaxError, TypeError, ValueError):
        return None

def eval_node(node, variables):
    if isinstance(node, ast.Num):  # <number>
        return node.n
    elif isinstance(node, ast.BinOp):  # <left> <operator> <right>
        left = eval_node(node.left, variables)
        right = eval_node(node.right, variables)
        op_type = type(node.op)
        if op_type in OPERATORS:
            if op_type == ast.BinOp:
                op = OPERATORS[op_type]
                return op(left, right)
            else:
                return OPERATORS[op_type](left, right)
        else:
            return None
    elif isinstance(node, ast.UnaryOp):  # - <operand>
        operand = eval_node(node.operand, variables)
        op_type = type(node.op)
        if op_type in OPERATORS:
            return OPERATORS[op_type](operand)
        else:
            return None
    elif isinstance(node, ast.Name):  # <variable>
        if node.id in variables:
            return variables[node.id]
        else:
            return None
    else:
        return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_templates.py TEMPLATE_PATH JSON_PATH")
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        with open(json_path, 'r') as json_file:
            variables = json.load(json_file)
            if not all(isinstance(value, int) for value in variables.values()):
                raise ValueError("All JSON values must be integers.")
    except (json.JSONDecodeError, FileNotFoundError, ValueError) as e:
        print(f"Error: Unable to read or parse JSON file: {json_path} - {e}")
        sys.exit(1)

    try:
        with open(template_path, 'r') as template_file:
            lines = template_file.readlines()
    except FileNotFoundError:
        print(f"Error: Template file not found: {template_path}")
        sys.exit(1)

    for line_number, line in enumerate(lines, start=1):
        match = re.search(r'{{\s*(.*?)\s*}}', line)
        if match:
            expression = match.group(1)
            result = evaluate_expression(expression, variables)
            if result is not None:
                print(line.replace(match.group(0), str(result)), end='')
            else:
                with open('errors.log', 'a') as error_log:
                    if any(var in expression for var in variables):
                        error_log.write(f"Line {line_number}: expression did not evaluate to an integer\n")
                    else:
                        error_log.write(f"Line {line_number}: missing variable {expression}\n")
        else:
            print(line, end='')

if __name__ == "__main__":
    main()

