import sys
import os
import re
import subprocess
import ast

def evaluate_expression(expression):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')
        # Define a set of allowed operations
        allowed_operations = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Num,
                              ast.Add, ast.Sub, ast.Mult, ast.UAdd, ast.USub)
        # Check if the expression contains only allowed operations
        for node in ast.walk(tree):
            if not isinstance(node, allowed_operations):
                raise ValueError("Invalid operation in expression")
        # Evaluate the expression safely
        return str(eval(compile(tree, filename="<ast>", mode="eval")))
    except Exception as e:
        return f"Error evaluating expression '{expression}': {e}"

def process_template(template):
    pattern = r'\{\{(.*?)\}\}'
    return re.sub(pattern, lambda match: evaluate_expression(match.group(1)), template)

def main():
    if len(sys.argv) != 2:
        print("Usage: python templated_run.py <templates_file>")
        sys.exit(1)

    templates_file = sys.argv[1]

    # Sanitize the file path
    templates_file = os.path.abspath(templates_file)
    if not os.path.isfile(templates_file):
        print(f"Error: File '{templates_file}' not found.")
        sys.exit(1)

    try:
        with open(templates_file, 'r', encoding='utf-8') as file:
            for line in file:
                stripped_line = line.strip()
                if stripped_line:
                    command = process_template(stripped_line)
                    try:
                        # Use list to avoid shell=True and potential injection
                        result = subprocess.run(command.split(), check=True, text=True, capture_output=True)
                        print(result.stdout)
                    except subprocess.CalledProcessError as e:
                        print(f"Error executing command '{command}': {e}")
    except IOError as e:
        print(f"Error reading file '{templates_file}': {e}")

if __name__ == "__main__":
    main()

import os
import sys
import subprocess
from concurrent.futures import ThreadPoolExecutor
import shlex

def run_command(command, output_file):
    try:
        with open(output_file, 'w') as f:
            subprocess.run(shlex.split(command), stdout=f, stderr=subprocess.STDOUT, check=True)
    except subprocess.CalledProcessError as e:
        print(f"Error executing command '{command}': {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)

def validate_inputs(jobs_file, output_dir, max_parallel):
    if not os.path.isfile(jobs_file):
        raise ValueError(f"JOBS_FILE '{jobs_file}' does not exist.")
    if not os.path.isdir(output_dir):
        raise ValueError(f"OUTPUT_DIR '{output_dir}' does not exist.")
    if not os.access(output_dir, os.W_OK):
        raise PermissionError(f"OUTPUT_DIR '{output_dir}' is not writable.")
    try:
        max_parallel = int(max_parallel)
        if max_parallel <= 0:
            raise ValueError
    except ValueError:
        raise ValueError("MAX_PARALLEL must be a positive integer.")
    return max_parallel

def main():
    if len(sys.argv) != 4:
        print("Usage: python batch_runner.py JOBS_FILE OUTPUT_DIR MAX_PARALLEL", file=sys.stderr)
        sys.exit(1)

    jobs_file = sys.argv[1]
    output_dir = sys.argv[2]
    max_parallel = sys.argv[3]

    try:
        max_parallel = validate_inputs(jobs_file, output_dir, max_parallel)
    except (ValueError, PermissionError) as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)

    try:
        with open(jobs_file, 'r') as f:
            commands = [line.strip() for line in f if line.strip()]

        command_count = 0
        for i in range(0, len(commands), max_parallel):
            group = commands[i:i + max_parallel]
            command_count += len(group)
            with ThreadPoolExecutor(max_workers=max_parallel) as executor:
                futures = [
                    executor.submit(run_command, cmd, os.path.join(output_dir, f"{i + j + 1}.out"))
                    for j, cmd in enumerate(group)
                ]
                for future in futures:
                    future.result()

        print(f"finished {command_count} commands")
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import subprocess
import xml.etree.ElementTree as ET
import json
import shlex
import logging

def validate_xml_structure(root):
    if root.tag != 'jobs':
        raise ValueError("Root element is not <jobs>")
    for job in root.findall('job'):
        if 'name' not in job.attrib or 'command' not in job.attrib:
            raise ValueError("Job element is missing 'name' or 'command' attribute")

def sanitize_filename(name):
    return ''.join(c for c in name if c.isalnum() or c in ('-', '_', '.'))

def main():
    logging.basicConfig(level=logging.INFO)

    if len(sys.argv) != 2:
        print("Usage: python jobrunner.py <path_to_xml_file>")
        sys.exit(1)

    xml_file_path = sys.argv[1]
    try:
        tree = ET.parse(xml_file_path)
        root = tree.getroot()
        validate_xml_structure(root)
    except ET.ParseError:
        logging.error("Error: Could not parse the XML file.")
        sys.exit(1)
    except FileNotFoundError:
        logging.error("Error: XML file not found.")
        sys.exit(1)
    except ValueError as ve:
        logging.error(f"Error: Invalid XML structure - {ve}")
        sys.exit(1)

    for job in root.findall('job'):
        name = job.get('name')
        command = job.get('command')
        sanitized_name = sanitize_filename(name)
        cache_file = f"{sanitized_name}.cache"

        if os.path.exists(cache_file):
            try:
                with open(cache_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    output = data.get('output', '')
            except json.JSONDecodeError:
                logging.error(f"Error: Could not parse cache file for job '{name}'.")
                sys.exit(1)
        else:
            try:
                command_list = shlex.split(command)
                result = subprocess.run(command_list, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                output = result.stdout
                with open(cache_file, 'w', encoding='utf-8') as f:
                    json.dump({'output': output}, f, ensure_ascii=False)
            except subprocess.CalledProcessError as e:
                logging.error(f"Error: Command '{command}' failed for job '{name}'.")
                sys.exit(1)
            except FileNotFoundError:
                logging.error(f"Error: Command '{command}' not found for job '{name}'.")
                sys.exit(1)

        print(f"--- {name} ---")
        print(output)
        print()

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import hashlib
import os
import logging
from pathlib import Path

def validate_file_path(file_path):
    if not os.path.isfile(file_path):
        raise ValueError(f"Invalid file path: {file_path}")

def validate_command(command):
    if not isinstance(command, str) or not command.strip():
        raise ValueError(f"Invalid command: {command}")

def main():
    logging.basicConfig(level=logging.INFO)

    if len(sys.argv) != 4:
        logging.error("Incorrect number of arguments")
        sys.exit(1)

    jobs_json_path = sys.argv[1]
    results_json_path = sys.argv[2]
    key_file_path = sys.argv[3]

    try:
        validate_file_path(jobs_json_path)
        validate_file_path(key_file_path)
    except ValueError as e:
        logging.error(str(e))
        sys.exit(1)

    try:
        with open(jobs_json_path, 'r') as jobs_file:
            jobs = json.load(jobs_file)
    except (json.JSONDecodeError, IOError) as e:
        logging.error(f"Error reading jobs JSON: {e}")
        sys.exit(1)

    results = []
    for job in jobs:
        try:
            validate_command(job)
            result = subprocess.run(job, shell=False, capture_output=True, text=True, check=True)
            results.append(result.stdout.strip())
        except subprocess.CalledProcessError as e:
            logging.error(f"Command failed: {job}, Error: {e}")
            sys.exit(1)

    try:
        with open(results_json_path, 'w') as results_file:
            json.dump(results, results_file)
    except IOError as e:
        logging.error(f"Error writing results JSON: {e}")
        sys.exit(1)

    try:
        with open(key_file_path, 'rb') as key_file:
            key_bytes = key_file.read()
    except IOError as e:
        logging.error(f"Error reading key file: {e}")
        sys.exit(1)

    try:
        with open(results_json_path, 'rb') as results_file:
            results_bytes = results_file.read()
    except IOError as e:
        logging.error(f"Error reading results JSON: {e}")
        sys.exit(1)

    hasher = hashlib.pbkdf2_hmac('sha256', key_bytes, b'salt', 100000)
    hasher.update(results_bytes)
    signature = hasher.digest()

    sig_file_path = Path(results_json_path).with_suffix('.sig')
    try:
        with open(sig_file_path, 'wb') as sig_file:
            sig_file.write(signature)
    except IOError as e:
        logging.error(f"Error writing signature file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import shlex
import re

def is_safe_expression(expression):
    # Allow only safe operations and literals
    safe_pattern = re.compile(r"^[a-zA-Z0-9_'\"]+$")
    return safe_pattern.match(expression) is not None

def main():
    if len(sys.argv) != 2:
        print("Usage: python runchecks.py <path_to_json_file>")
        return

    json_file_path = sys.argv[1]

    try:
        with open(json_file_path, 'r') as file:
            data = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading JSON file: {e}")
        return

    for item in data:
        command = item.get('command', '')
        expect = item.get('expect', '')

        if not command or not expect:
            print("FAIL")
            continue

        try:
            # Use shlex.split to safely split the command
            command_args = shlex.split(command)
            result = subprocess.run(command_args, capture_output=True, text=True)
            out = result.stdout

            if not is_safe_expression(expect):
                print("FAIL")
                continue

            # Use a restricted environment for eval
            safe_dict = {'out': out}
            if eval(expect, {"__builtins__": None}, safe_dict):
                print("PASS")
            else:
                print("FAIL")
        except (subprocess.SubprocessError, SyntaxError, NameError) as e:
            print("FAIL")

