import json
import subprocess
import time
import os
import shlex

def validate_command(command):
    # Ensure the command is a safe string
    if not isinstance(command, str):
        raise ValueError("Command must be a string")
    # Split the command into parts and validate each part
    parts = shlex.split(command)
    if not parts:
        raise ValueError("Command cannot be empty")
    # Check for potentially dangerous characters
    for part in parts:
        if any(char in part for char in ';&|`$'):
            raise ValueError("Command contains potentially dangerous characters")
    return parts

def run_commands():
    # Ensure the input file is in the current working directory
    input_file = os.path.join(os.getcwd(), 'commands.json')
    output_file = os.path.join(os.getcwd(), 'results.json')

    if not os.path.isfile(input_file):
        raise FileNotFoundError(f"Input file {input_file} not found")

    with open(input_file, 'r') as f:
        commands = json.load(f)

    if not isinstance(commands, list):
        raise ValueError("Input must be a JSON array of strings")

    results = []

    for command in commands:
        try:
            safe_command = validate_command(command)
            process = subprocess.Popen(safe_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = process.communicate()
            results.append({
                'command': command,
                'stdout': stdout.decode('utf-8'),
                'exit_code': process.returncode
            })
        except Exception as e:
            results.append({
                'command': command,
                'stdout': '',
                'exit_code': -1,
                'error': str(e)
            })
        time.sleep(0.4)

    # Write results to output file with restricted permissions
    with open(output_file, 'w') as f:
        json.dump(results, f)
    os.chmod(output_file, 0o600)  # Read and write permissions for the owner only

if __name__ == "__main__":
    run_commands()

import sys
import json
import os
import subprocess
import requests
from datetime import datetime, timezone
from urllib.parse import urlparse
import shlex

def log_message(tag, message):
    timestamp = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    log_line = f"{timestamp} {tag} {message}"
    print(log_line)
    try:
        with open(config['log_path'], 'a') as log_file:
            log_file.write(log_line + '\n')
    except IOError:
        print(log_line)
        sys.exit(1)

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        log_message('ERROR', 'Invalid number of arguments')
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (IOError, json.JSONDecodeError):
        log_message('ERROR', 'Failed to read or parse config file')
        sys.exit(1)

    required_fields = ['url', 'command', 'state_path', 'log_path']
    if not all(field in config and isinstance(config[field], str) for field in required_fields):
        log_message('ERROR', 'Missing or invalid required fields in config')
        sys.exit(1)

    if not is_valid_url(config['url']):
        log_message('ERROR', 'Invalid URL in config')
        sys.exit(1)

    try:
        response = requests.get(config['url'], timeout=10, verify=True)
        response.raise_for_status()
        build_data = response.json()
        if 'build_id' not in build_data or not isinstance(build_data['build_id'], str):
            log_message('ERROR', 'Invalid build_id in response')
            sys.exit(1)
    except requests.RequestException as e:
        log_message('ERROR', f'HTTP request failed: {str(e)}')
        sys.exit(1)

    build_id = build_data['build_id']
    try:
        if os.path.exists(config['state_path']):
            with open(config['state_path'], 'r') as state_file:
                current_state = state_file.read().strip()
        else:
            current_state = None
    except IOError:
        log_message('ERROR', 'Failed to read state_path')
        sys.exit(1)

    if current_state == build_id:
        log_message('SAME', f'build_id={build_id}')
    else:
        try:
            command_parts = shlex.split(config['command'])
            result = subprocess.run(command_parts, check=True)
            if result.returncode == 0:
                try:
                    with open(config['state_path'], 'w') as state_file:
                        state_file.write(build_id)
                    log_message('CHANGED', f'old={current_state} new={build_id}')
                except IOError:
                    log_message('ERROR', 'Failed to write to state_path')
                    sys.exit(1)
            else:
                log_message('ERROR', 'Command exited with non-zero status')
                sys.exit(1)
        except subprocess.CalledProcessError as e:
            log_message('ERROR', f'Command execution failed: {str(e)}')
            sys.exit(1)

if __name__ == '__main__':
    main()

import sys
import os
import asyncio
import aiohttp
import subprocess
import shlex
import re
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_filename(index):
    return f"{index}.dat"

async def download_and_process(session, url, index, command):
    try:
        if not is_valid_url(url):
            print(f"{index} ERROR")
            return

        async with session.get(url, ssl=False) as response:
            if response.status // 100 == 2:
                filename = sanitize_filename(index)
                with open(filename, 'wb') as f:
                    while True:
                        chunk = await response.content.read(1024)
                        if not chunk:
                            break
                        f.write(chunk)
                process = await asyncio.create_subprocess_exec(
                    *command, filename,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL
                )
                await process.wait()
                print(f"{index} {process.returncode}")
            else:
                print(f"{index} ERROR")
    except aiohttp.ClientError:
        print(f"{index} ERROR")
    except Exception:
        print(f"{index} ERROR")

async def main(urls_file, command):
    with open(urls_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    connector = aiohttp.TCPConnector(limit=3)
    async with aiohttp.ClientSession(connector=connector) as session:
        tasks = [
            download_and_process(session, url, i+1, command)
            for i, url in enumerate(urls)
        ]
        await asyncio.gather(*tasks)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(1)
    urls_file, command = sys.argv[1], shlex.split(sys.argv[2])
    asyncio.run(main(urls_file, command))

import sys
import os
import json
import subprocess
import re

def evaluate_expression(expr, vars):
    parts = re.split(r'\s*\+\s*', expr)
    return sum(vars[part.strip()] for part in parts)

def validate_vars(vars):
    for var, value in vars.items():
        if not isinstance(value, int):
            raise ValueError(f"Invalid value for {var}: {value}")
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', var):
            raise ValueError(f"Invalid variable name: {var}")

def validate_command(command):
    if not isinstance(command, str):
        raise ValueError("Command must be a string")
    if re.search(r'[;&|`$]', command):
        raise ValueError("Command contains disallowed characters")

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_job.py job.json", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as f:
            job = json.load(f)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error reading job file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        token_env = job['token_env']
        vars = job['vars']
        command = job['command']
    except KeyError as e:
        print(f"Missing required key in job file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        validate_vars(vars)
        validate_command(command)
    except ValueError as e:
        print(f"Invalid job configuration: {e}", file=sys.stderr)
        sys.exit(1)

    token = os.environ.get(token_env)
    if token is None:
        print(f"missing token: {token_env}", file=sys.stderr)
        sys.exit(2)

    for var, value in vars.items():
        command = command.replace(f"{{{{{var}}}}}", str(value))

    for expr in vars.keys():
        if '+' in expr:
            command = command.replace(f"{{{{{expr}}}}}", str(evaluate_expression(expr, vars)))

    env = {k: v for k, v in os.environ.items() if k in ('PATH', 'HOME', 'USER')}
    env['TOKEN'] = token

    try:
        process = subprocess.Popen(command, shell=False, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()

        sys.stdout.write(stdout)
        sys.stderr.write(stderr)
        sys.exit(process.returncode)
    except subprocess.SubprocessError as e:
        print(f"Error executing command: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import json
import requests
import subprocess
import re
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def is_valid_token(token):
    return isinstance(token, str) and len(token) > 0

def sanitize_command(cmd):
    # Allow only alphanumeric characters, spaces, and basic shell operators
    return re.sub(r'[^a-zA-Z0-9\s\.\-_\/\:\(\)]', '', cmd)

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python run_pending.py <base_url> <token_file_path>\n")
        sys.exit(2)

    base_url = sys.argv[1]
    token_file_path = sys.argv[2]

    if not is_valid_url(base_url):
        sys.stderr.write("Invalid base URL\n")
        sys.exit(2)

    try:
        with open(token_file_path, 'r') as token_file:
            token = token_file.read().rstrip('\n')
    except Exception as e:
        sys.stderr.write(f"Error reading token file: {e}\n")
        sys.exit(2)

    if not is_valid_token(token):
        sys.stderr.write("Invalid token\n")
        sys.exit(2)

    headers = {
        'Authorization': f'Bearer {token}'
    }

    try:
        response = requests.get(f"{base_url}/pending", headers=headers, verify=True)
        if response.status_code != 200:
            sys.stderr.write(f"Failed to fetch pending commands: HTTP {response.status_code}\n")
            sys.exit(2)

        pending_commands = response.json()
        if not isinstance(pending_commands, list) or not all(isinstance(cmd, dict) and 'id' in cmd and 'cmd' in cmd for cmd in pending_commands):
            sys.stderr.write("Invalid response format\n")
            sys.exit(2)

    except (requests.RequestException, json.JSONDecodeError) as e:
        sys.stderr.write(f"Error fetching or parsing pending commands: {e}\n")
        sys.exit(2)

    for command in pending_commands:
        cmd_id = command['id']
        cmd = sanitize_command(command['cmd'])
        try:
            result = subprocess.run(cmd, shell=True, check=True, capture_output=True, text=True)
            exit_code = result.returncode
        except subprocess.CalledProcessError as e:
            exit_code = e.returncode

        log_entry = json.dumps({'id': cmd_id, 'exit_code': exit_code})
        with open('run.log', 'a') as log_file:
            log_file.write(log_entry + '\n')
            log_file.flush()

        if exit_code != 0:
            sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import subprocess
import hashlib
import json
import shlex

def compute_keyed_digest(stdout_bytes, key):
    key_bytes = key.encode('utf-8')
    hmac = hashlib.new('sha256', key_bytes)
    hmac.update(stdout_bytes)
    return hmac.hexdigest()

def validate_and_sanitize_input(xml_file_path):
    if len(sys.argv) != 2:
        raise ValueError("Exactly one argument (XML file path) is required.")
    return xml_file_path

def parse_xml_safely(xml_file_path):
    try:
        tree = ET.iterparse(xml_file_path, events=('start', 'end'))
        root = None
        for event, elem in tree:
            if event == 'start' and root is None:
                if elem.tag != 'jobs':
                    raise ValueError("Root element must be <jobs>.")
                root = elem
            elif event == 'end' and elem.tag == 'job':
                if not elem.get('name') or not elem.find('command') or not elem.find('key'):
                    raise ValueError("Each <job> must have a name, <command>, and <key>.")
                yield elem
                elem.clear()
    except ET.ParseError as e:
        raise ValueError(f"XML parsing error: {e}")

def main():
    xml_file_path = validate_and_sanitize_input(sys.argv[1])

    for job in parse_xml_safely(xml_file_path):
        name = job.get('name')
        command = job.find('command').text
        key = job.find('key').text

        try:
            process = subprocess.run(shlex.split(command), capture_output=True, check=True)
            stdout_bytes = process.stdout
        except subprocess.CalledProcessError as e:
            print(json.dumps({'name': name, 'error': 'Command execution failed'}))
            continue
        except FileNotFoundError:
            print(json.dumps({'name': name, 'error': 'Command not found'}))
            continue

        digest = compute_keyed_digest(stdout_bytes, key)
        job_output = {'name': name, 'digest': digest}
        print(json.dumps(job_output))

if __name__ == '__main__':
    main()

import sys
import json
import subprocess
import hashlib
import os
import re

def validate_cmd(cmd):
    # Only allow alphanumeric characters, spaces, and basic shell operators
    if not re.match(r'^[a-zA-Z0-9\s\.\-_/]+$', cmd):
        raise ValueError("Invalid command")

def validate_expr(expr):
    # Only allow safe operations and variables
    if not re.match(r'^[a-zA-Z0-9_+\-*/()\s]+$', expr):
        raise ValueError("Invalid expression")

def safe_eval(expr, output):
    # Create a safe environment for eval
    safe_dict = {
        'output': output,
        '__builtins__': {}
    }
    return eval(expr, {"__builtins__": None}, safe_dict)

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <json_file_path>")
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading JSON file: {e}")
        sys.exit(1)

    if 'cmd' not in data or 'expr' not in data:
        print("JSON file must contain 'cmd' and 'expr' fields")
        sys.exit(1)

    try:
        validate_cmd(data['cmd'])
        validate_expr(data['expr'])
    except ValueError as e:
        print(f"Validation error: {e}")
        sys.exit(1)

    try:
        output = subprocess.check_output(data['cmd'], shell=False, text=True)
    except subprocess.CalledProcessError as e:
        print(f"Command execution failed: {e}")
        sys.exit(1)

    try:
        expr_result = safe_eval(data['expr'], output)
        print(expr_result)
    except Exception as e:
        print(f"Error evaluating expression: {e}")
        sys.exit(1)

    try:
        secret = bytes.fromhex(os.environ.get('JOB_SECRET', ''))
    except ValueError:
        print("Invalid JOB_SECRET environment variable")
        sys.exit(1)

    if not secret:
        print("JOB_SECRET environment variable is not set")
        sys.exit(1)

    digest = hashlib.sha256(str(expr_result).encode('utf-8')).hexdigest()
    print(f"digest {digest}")

if __name__ == "__main__":
    main()

import sys
import os
import subprocess
import hashlib
import shlex

def escape_text(text):
    return text.replace('\n', '\\n').replace('\t', '\\t')

def compute_hash(command, exit_status, output):
    hash_input = f"{command}\t{exit_status}\t{output}".encode('utf-8')
    return hashlib.sha256(hash_input).hexdigest()

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python3 runlog.py <commands_file> <log_file>\n")
        sys.exit(1)

    commands_file = sys.argv[1]
    log_file = sys.argv[2]

    try:
        with open(commands_file, 'r', encoding='utf-8') as cmd_file:
            commands = cmd_file.readlines()
    except OSError as e:
        sys.stderr.write(f"{e.strerror}\n")
        sys.exit(1)

    try:
        with open(log_file, 'a', encoding='utf-8') as log:
            for command in commands:
                command = command.strip()
                if not command:
                    continue

                try:
                    args = shlex.split(command)
                    result = subprocess.run(args, capture_output=True, text=True, timeout=10)
                    exit_status = result.returncode
                    output = result.stdout + result.stderr
                except FileNotFoundError:
                    exit_status = 127
                    output = f"Command not found: {command}"
                except subprocess.TimeoutExpired:
                    exit_status = 124
                    output = "Command timed out"
                except Exception as e:
                    exit_status = 1
                    output = str(e)

                escaped_command = escape_text(command)
                escaped_output = escape_text(output)
                hash_digest = compute_hash(escaped_command, exit_status, escaped_output)

                log_entry = f"{escaped_command}\t{exit_status}\t{escaped_output}\t{hash_digest}\n"
                log.write(log_entry)

    except OSError as e:
        sys.stderr.write(f"{e.strerror}\n")
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import time
import hashlib
import subprocess
import shlex
import logging
from pathlib import Path

def validate_input_file(file_path):
    if not Path(file_path).is_file():
        raise FileNotFoundError(f"File not found: {file_path}")

def validate_command(command):
    if not isinstance(command, str) or not command.strip():
        raise ValueError("Invalid command")

def run_command(command):
    try:
        result = subprocess.run(shlex.split(command), capture_output=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        logging.error(f"Command failed: {e}")
        return b''

def main():
    logging.basicConfig(level=logging.INFO)

    if len(sys.argv) != 3:
        print("Usage: python3 batchrun.py jobs.txt manifest.txt")
        return

    jobs_file = sys.argv[1]
    manifest_file = sys.argv[2]

    try:
        validate_input_file(jobs_file)
        validate_input_file(manifest_file)
    except FileNotFoundError as e:
        logging.error(e)
        return

    with open(jobs_file, 'r', encoding='utf-8') as f:
        lines = [line.strip() for line in f if line.strip()]

    results = []
    last_start_time = None

    for i in range(0, len(lines), 2):
        name, command = lines[i].split('\t', 1)
        try:
            validate_command(command)
        except ValueError as e:
            logging.error(f"Invalid command for job {name}: {e}")
            continue

        if i > 0:
            if last_start_time is not None:
                elapsed_time = time.time() - last_start_time
                if elapsed_time < 1.5:
                    time.sleep(1.5 - elapsed_time)
            last_start_time = time.time()

        output = run_command(command)
        digest = hashlib.sha256(output).hexdigest()
        results.append((name, digest))

    try:
        with open(manifest_file, 'w', encoding='utf-8') as f:
            for name, digest in results:
                f.write(f"{name} {digest}\n")
    except IOError as e:
        logging.error(f"Failed to write manifest file: {e}")

if __name__ == "__main__":
    main()

import sys
import subprocess
import concurrent.futures
import html
import os
import re

def read_commands(file_path):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Commands file not found: {file_path}")
    with open(file_path, 'r') as file:
        return [line.strip() for line in file if line.strip()]

def execute_command(command):
    if not re.match(r'^[a-zA-Z0-9\s._-]+$', command):
        raise ValueError(f"Invalid command: {command}")
    result = subprocess.run(command, shell=False, capture_output=True, text=True)
    return command, result.returncode, result.stdout.strip()

def generate_html_report(results, output_file):
    with open(output_file, 'w') as file:
        file.write('<html><head><title>Commands report</title></head><body><table border="1">\n')
        file.write('<tr><th>Command</th><th>Exit code</th><th>Stdout</th></tr>\n')
        for command, exit_code, stdout in results:
            file.write(f'<tr><td>{html.escape(command)}</td><td>{exit_code}</td><td>{html.escape(stdout)}</td></tr>\n')
        file.write('</table></body></html>')

def main():
    if len(sys.argv) < 3:
        print("Usage: python report.py <commands.txt> <report.html> [--concurrency <n>]")
        sys.exit(1)

    commands_file = sys.argv[1]
    report_file = sys.argv[2]
    concurrency = 4

    if len(sys.argv) > 3 and sys.argv[3] == '--concurrency':
        try:
            concurrency = int(sys.argv[4])
            if concurrency <= 0:
                raise ValueError
        except (IndexError, ValueError):
            print("Invalid concurrency value. Using default of 4.")

    try:
        commands = read_commands(commands_file)
    except FileNotFoundError as e:
        print(e)
        sys.exit(1)

    results = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
        future_to_command = {executor.submit(execute_command, cmd): cmd for cmd in commands}
        for future in concurrent.futures.as_completed(future_to_command):
            try:
                results.append(future.result())
            except ValueError as e:
                print(e)

    try:
        generate_html_report(results, report_file)
    except IOError as e:
        print(f"Error writing to report file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import re
import subprocess
import concurrent.futures
from argparse import ArgumentParser
import os

def evaluate_expression(expr):
    # Use a safe evaluation method by parsing the expression manually
    def parse_expression(expr):
        tokens = re.findall(r'\d+|[+*]', expr)
        if not tokens:
            raise ValueError("Invalid expression")
        result = int(tokens[0])
        i = 1
        while i < len(tokens):
            if tokens[i] == '*':
                result *= int(tokens[i + 1])
            elif tokens[i] == '+':
                result += int(tokens[i + 1])
            i += 2
        return result

    return parse_expression(expr)

def replace_placeholders(command):
    return re.sub(r'{{(.*?)}}', lambda match: str(evaluate_expression(match.group(1))), command)

def run_command(command):
    try:
        # Use list to avoid shell injection
        result = subprocess.run(command.split(), capture_output=True, text=True)
        return {
            'command': command,
            'output': result.stdout + result.stderr,
            'exit_code': result.returncode
        }
    except Exception as e:
        return {
            'command': command,
            'output': '',
            'exit_code': -1
        }

def main():
    parser = ArgumentParser(description='Run commands from a file with optional concurrency.')
    parser.add_argument('file_path', type=str, help='Path to the file containing commands.')
    parser.add_argument('--concurrency', type=int, default=1, help='Number of concurrent commands to run.')
    args = parser.parse_args()

    # Validate file path
    if not os.path.isfile(args.file_path):
        print("Error: The specified file does not exist.")
        sys.exit(1)

    with open(args.file_path, 'r') as file:
        commands = [line.strip() for line in file if line.strip()]

    replaced_commands = [replace_placeholders(cmd) for cmd in commands]

    # Limit concurrency to a reasonable maximum
    max_concurrency = 10
    concurrency = min(args.concurrency, max_concurrency)

    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = {executor.submit(run_command, cmd): cmd for cmd in replaced_commands}
        for future in concurrent.futures.as_completed(futures):
            print(json.dumps(future.result()))

if __name__ == '__main__':
    main()

import sys
import subprocess
import os
import shlex
from concurrent.futures import ThreadPoolExecutor, as_completed

def run_command(index, command):
    try:
        # Use shlex.split to safely split the command into arguments
        args = shlex.split(command)
        result = subprocess.run(args, check=False, capture_output=True)
        print(f"DONE {index} exit={result.returncode}")
        return result.returncode
    except FileNotFoundError:
        print(f"DONE {index} exit=error")
        return "error"
    except Exception as e:
        print(f"DONE {index} exit=error")
        return "error"

def validate_file_path(file_path):
    # Ensure the file path is within the current directory to prevent path traversal
    return os.path.abspath(file_path).startswith(os.path.abspath('.'))

def main():
    if len(sys.argv) != 3:
        print("Usage: python runbatch.py <manifest_path> <max_parallel>")
        sys.exit(1)

    manifest_path = sys.argv[1]
    max_parallel = sys.argv[2]

    # Validate max_parallel is a positive integer
    try:
        max_parallel = int(max_parallel)
        if max_parallel <= 0:
            raise ValueError
    except ValueError:
        print("Error: <max_parallel> must be a positive integer.")
        sys.exit(1)

    # Validate the manifest path
    if not validate_file_path(manifest_path):
        print("Error: Invalid file path.")
        sys.exit(1)

    try:
        with open(manifest_path, 'r', encoding='utf-8') as file:
            commands = [line.strip() for line in file if line.strip()]
    except Exception as e:
        print(f"Error reading manifest: {e}")
        sys.exit(1)

    with ThreadPoolExecutor(max_workers=max_parallel) as executor:
        futures = {executor.submit(run_command, i, cmd): i for i, cmd in enumerate(commands)}
        results = []
        for future in as_completed(futures):
            result = future.result()
            results.append(result)

    if all(result == 0 for result in results if isinstance(result, int)):
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import sqlite3
import os
import re

def validate_database_path(path):
    # Ensure the path is absolute and within a safe directory
    abs_path = os.path.abspath(path)
    if not abs_path.startswith('/safe/directory'):
        raise ValueError("Invalid database path")
    return abs_path

def validate_query(query):
    # Ensure the query contains exactly one '?' and is safe
    if query.count('?') != 1:
        raise ValueError("Query must contain exactly one '?'")
    # Basic SQL injection prevention: no semicolons, basic keywords
    if re.search(r';|\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|TABLE|FROM|WHERE|AND|OR)\b', query, re.IGNORECASE):
        raise ValueError("Query contains potentially unsafe SQL keywords")
    return query

def parse_xml_config(xml_config_file):
    # Parse XML securely without XXE
    parser = ET.XMLParser(forbid_dtd=True)
    tree = ET.parse(xml_config_file, parser=parser)
    root = tree.getroot()

    database_path = root.find('database').get('path')
    query = root.find('query').text

    return validate_database_path(database_path), validate_query(query)

def main():
    if len(sys.argv) != 3:
        print("Usage: python run_queries.py <xml_config_file> <values_file>")
        sys.exit(1)

    xml_config_file = sys.argv[1]
    values_file = sys.argv[2]

    try:
        database_path, query = parse_xml_config(xml_config_file)
    except Exception as e:
        print(f"Error parsing XML configuration: {e}")
        sys.exit(1)

    try:
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        print(f"Database connection error: {e}")
        sys.exit(1)

    try:
        with open(values_file, 'r', encoding='utf-8') as file:
            for line in file:
                value = line.rstrip('\n\r')
                try:
                    cursor.execute(query, (value,))
                    rows = cursor.fetchall()
                    for row in rows:
                        print(','.join(map(str, row)))
                except sqlite3.Error as e:
                    print(f"Query execution error: {e}")
    except Exception as e:
        print(f"Error reading values file: {e}")
    finally:
        conn.close()

if __name__ == "__main__":
    main()

import sqlite3
import time
import os
import sys
from collections import deque
import logging

def validate_file_path(file_path, mode='r'):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")
    if mode == 'r' and not os.path.isfile(file_path):
        raise ValueError(f"The path {file_path} is not a valid file.")
    if mode == 'w' and not os.access(os.path.dirname(file_path), os.W_OK):
        raise PermissionError(f"The file {file_path} is not writable.")

def main():
    if len(sys.argv) != 4:
        print("Usage: python script.py INPUT_FILE DATABASE_FILE OUTPUT_FILE")
        sys.exit(1)

    input_file = sys.argv[1]
    database_file = sys.argv[2]
    output_file = sys.argv[3]

    try:
        validate_file_path(input_file, 'r')
        validate_file_path(database_file, 'r')
        validate_file_path(output_file, 'w')
    except (FileNotFoundError, ValueError, PermissionError) as e:
        logging.error(e)
        sys.exit(1)

    logging.basicConfig(filename='script.log', level=logging.INFO)

    conn = sqlite3.connect(database_file)
    cursor = conn.cursor()

    try:
        with open(input_file, 'r') as infile, open(output_file, 'w') as outfile:
            query_times = deque()
            for username in infile:
                username = username.strip()
                if not username:
                    continue

                current_time = time.time()
                while query_times and current_time - query_times[0] > 1:
                    query_times.popleft()

                if len(query_times) >= 20:
                    time.sleep(1 - (current_time - query_times[0]))

                try:
                    cursor.execute("SELECT email FROM users WHERE username = ?", (username,))
                    result = cursor.fetchone()
                    if result:
                        outfile.write(f"{result[0]}\n")
                except sqlite3.Error as e:
                    logging.error(f"Database error for username {username}: {e}")

                query_times.append(time.time())
    except IOError as e:
        logging.error(f"File error: {e}")
    finally:
        conn.close()

if __name__ == "__main__":
    main()

import sys
import os
import configparser

def sanitize_path(path):
