import sys
import os
import html
import re

def validate_input(note):
    # Basic validation to prevent HTML and JavaScript injection
    if re.search(r'<[^>]+>', note) or re.search(r'javascript:', note, re.IGNORECASE):
        raise ValueError("Invalid note content detected.")
    return note

def validate_output_path(output_path):
    # Prevent directory traversal by ensuring the path is within the current directory
    if os.path.isabs(output_path) or '..' in output_path:
        raise ValueError("Invalid output path.")
    return output_path

def read_notes_from_file():
    if os.path.exists('notes.dat'):
        with open('notes.dat', 'r', encoding='utf-8') as file:
            return [line.rstrip('\n') for line in file]
    return []

def write_notes_to_file(notes):
    try:
        with open('notes.dat', 'w', encoding='utf-8') as file:
            for note in notes:
                file.write(note + '\n')
    except IOError as e:
        print(f"Error writing to notes.dat: {e}", file=sys.stderr)
        sys.exit(1)

def generate_html(notes, output_path):
    try:
        with open(output_path, 'w', encoding='utf-8') as file:
            file.write('<ol>\n')
            for note in notes:
                file.write(f'  <li>{html.escape(note)}</li>\n')
            file.write('</ol>\n')
    except IOError as e:
        print(f"Error writing to {output_path}: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python notes_app.py <output_html_path>")
        sys.exit(1)

    output_html_path = sys.argv[1]
    try:
        output_html_path = validate_output_path(output_html_path)
    except ValueError as e:
        print(e, file=sys.stderr)
        sys.exit(1)

    input_notes = []
    try:
        for line in sys.stdin:
            note = line.rstrip('\n')
            validated_note = validate_input(note)
            input_notes.append(validated_note)
    except Exception as e:
        print(f"Error reading input: {e}", file=sys.stderr)
        sys.exit(1)

    existing_notes = read_notes_from_file()
    updated_notes = existing_notes + input_notes
    write_notes_to_file(updated_notes)
    generate_html(updated_notes, output_html_path)

if __name__ == "__main__":
    main()

import sys
import os
import re

def load_tasks():
    if os.path.exists('tasks.cache'):
        with open('tasks.cache', 'r') as file:
            return [line.strip() for line in file.readlines()]
    return []

def save_tasks(tasks):
    with open('tasks.cache', 'w') as file:
        for task in tasks:
            file.write(task + '\n')
    os.chmod('tasks.cache', 0o600)  # Set file permissions to read/write for owner only

def log_command(command, outcome):
    with open('tasks.log', 'a') as file:
        file.write(f"{command} {outcome}\n")
    os.chmod('tasks.log', 0o600)  # Set file permissions to read/write for owner only

def sanitize_input(input_line):
    # Remove any non-printable characters
    return re.sub(r'[^\x20-\x7E]', '', input_line)

def main():
    tasks = load_tasks()
    for line in sys.stdin:
        line = sanitize_input(line.strip())
        if not line:
            log_command('-', 'ok')
            continue

        parts = line.split(' ', 1)
        command = parts[0]

        if command == 'add':
            if len(parts) < 2 or not parts[1].strip():
                print("error: add requires text", file=sys.stderr)
                log_command(command, 'error')
            else:
                tasks.append(parts[1].strip())
                log_command(line, 'ok')
        elif command == 'list':
            for i, task in enumerate(tasks, 1):
                print(f"{i} {task}")
            log_command(command, 'ok')
        else:
            print(f"error: unknown command {command}", file=sys.stderr)
            log_command(command, 'error')

    save_tasks(tasks)

