import sys
import os
import re

def is_safe_path(path):
    # Ensure the path is within the current working directory
    return os.path.abspath(path).startswith(os.path.abspath(os.getcwd()))

def load_cache():
    cache = {}
    if os.path.exists('.stats_cache'):
        with open('.stats_cache', 'r') as cache_file:
            for line in cache_file:
                path, size = line.strip().split('\t')
                if is_safe_path(path):
                    cache[path] = int(size)
    return cache

def save_cache(cache):
    with open('.stats_cache', 'w') as cache_file:
        for path, size in cache.items():
            cache_file.write(f"{path}\t{size}\n")

def main():
    cache = load_cache()
    paths = [line.strip() for line in sys.stdin]

    for i in range(0, len(paths), 4):
        group = paths[i:i+4]
        for path in group:
            if not is_safe_path(path):
