import sys
import requests
import json
import re
from urllib.parse import urlparse
import ast

def is_safe_url(url):
    parsed_url = urlparse(url)
    return parsed_url.scheme in ['http', 'https']

def is_safe_expression(expression):
    try:
        tree = ast.parse(expression, mode='eval')
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Expression, ast.Num, ast.BinOp, ast.UnaryOp, ast.Name, ast.Load)):
                return False
        return True
    except SyntaxError:
        return False

def fetch_and_evaluate():
    input_path, output_path = sys.stdin.read().strip().split()

    with open(input_path, 'r') as infile:
        line = infile.readline().strip()
        url, expression = line.split(maxsplit=1)

    if not is_safe_url(url):
        raise ValueError("Unsafe URL scheme")

    if not is_safe_expression(expression):
        raise ValueError("Unsafe expression")

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Network error: {e}")

    placeholders = response.json()

    for name, value in placeholders.items():
        if not isinstance(value, (int, float)):
            raise ValueError(f"Invalid placeholder value for {name}")
        expression = expression.replace(f'{{{name}}}', str(value))

    try:
        result = eval(expression)
    except Exception as e:
        raise RuntimeError(f"Error evaluating expression: {e}")

    if isinstance(result, int):
        result_str = str(result)
    else:
        result_str = re.sub(r'\.?0+$', '', f'{result:.10g}')

    with open(output_path, 'w') as outfile:
        outfile.write(f'{url}\t{result_str}\n')

if __name__ == '__main__':
    fetch_and_evaluate()

import sys
import os
import requests
from urllib.parse import urlparse
from requests.exceptions import RequestException, Timeout, TooManyRedirects, HTTPError, ConnectionError

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_urls.py <file_path>")
        return

    file_path = sys.argv[1]
    if not os.path.isfile(file_path):
        print(f"Error: The file '{file_path}' does not exist.")
        return

    successful = 0
    failed = 0

    try:
        with open(file_path, 'r') as file, open('check.log', 'a') as log_file:
            for line in file:
                url = line.strip()
                if not is_valid_url(url):
                    failed += 1
                    log_file.write(f"{url} ERROR: Invalid URL\n")
                    continue

                try:
                    response = requests.get(url, timeout=10, verify=True, headers={'User-Agent': 'CustomScript/1.0'})
                    status_code = response.status_code
                    if 200 <= status_code <= 299:
                        successful += 1
                    else:
                        failed += 1
                    log_file.write(f"{url} {status_code}\n")
                except (Timeout, TooManyRedirects, HTTPError, ConnectionError) as e:
                    failed += 1
                    log_file.write(f"{url} ERROR: {str(e)}\n")
                except RequestException as e:
                    failed += 1
                    log_file.write(f"{url} ERROR: Unexpected error - {str(e)}\n")

    except IOError as e:
        print(f"Error: Unable to open or write to log file. {str(e)}")
        return

    print(f"Processed {successful + failed} URLs: {successful} successful, {failed} failed")

if __name__ == "__main__":
    main()

import sys
import os
import re

def evaluate_expression(expression, variables):
    allowed_names = set(variables.keys())
    allowed_operators = {'+', '-', '(', ')'}
    allowed_chars = allowed_names | allowed_operators | set('0123456789 ')

    if not all(char in allowed_chars for char in expression):
        return ''

    try:
        return str(eval(expression, {"__builtins__": None}, variables))
    except Exception:
        return ''

def sanitize_path(path):
    return os.path.normpath(path)

def main():
    input_lines = sys.stdin.read().strip().split('\n')
    if len(input_lines) < 2:
        print('ACCESS_DENIED')
        sys.exit(1)

    token = input_lines[0]
    template_path = sanitize_path(input_lines[1])
    name_to_integer = {}

    for line in input_lines[2:]:
        if '=' not in line:
            continue
        name, value = line.split('=', 1)
        if not name.isidentifier() or not value.isdigit():
            continue
        name_to_integer[name] = int(value)

    access_file_path = os.path.join(os.path.dirname(__file__), 'access.txt')
    try:
        with open(access_file_path, 'r') as access_file:
            first_line = access_file.readline().strip()
            if not first_line.endswith(':render') or first_line[:-7] != token:
                print('ACCESS_DENIED')
