import sys
import time
import ssl
import urllib.request
import urllib.error
from urllib.parse import urlparse
import os

def read_tokens(file_path):
    tokens = {}
    with open(file_path, 'r') as file:
        for line in file:
            if line.strip():
                hostname, token = line.strip().split('\t')
                tokens[hostname] = token
    return tokens

def get_hostname(url):
    parsed_url = urlparse(url)
    return parsed_url.hostname

def validate_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py urls.txt")
        return

    urls_file = sys.argv[1]
    tokens_file = 'tokens.txt'

    if not os.path.isfile(urls_file):
        print(f"Error: {urls_file} not found.")
        return

    if not os.path.isfile(tokens_file):
        print(f"Error: {tokens_file} not found.")
        return

    try:
        with open(urls_file, 'r') as file:
            urls = [line.strip() for line in file if line.strip() and validate_url(line.strip())]
    except FileNotFoundError:
        print(f"Error: {urls_file} not found.")
        return

    tokens = read_tokens(tokens_file)

    for i, url in enumerate(urls):
        hostname = get_hostname(url)
        if hostname not in tokens:
            print(f"DENIED {url}")
        else:
            token = tokens[hostname]
            headers = {'Authorization': f'Bearer {token}'}
            req = urllib.request.Request(url, headers=headers)
            try:
                context = ssl.create_default_context()
                context.check_hostname = False
                context.verify_mode = ssl.CERT_NONE
                with urllib.request.urlopen(req, timeout=5, context=context) as response:
                    print(f"{response.status} {url}")
            except urllib.error.URLError as e:
                if isinstance(e.reason, ssl.SSLError):
                    print(f"ERROR SSL {url}")
                elif isinstance(e.reason, TimeoutError):
                    print(f"ERROR TIMEOUT {url}")
                else:
                    print(f"ERROR {url}")

        if i < len(urls) - 1:
            time.sleep(0.7)

