    main()

import sys
import xml.etree.ElementTree as ET
import re
import ast
import operator

class ExpressionEvaluator:
    def __init__(self, variables):
        self.variables = variables
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.USub: operator.neg
        }

    def evaluate(self, expression):
        try:
            node = ast.parse(expression, mode='eval').body
            return self._evaluate_node(node)
        except Exception as e:
            raise ValueError(f"Invalid expression: {expression}") from e

    def _evaluate_node(self, node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._evaluate_node(node.left)
            right = self._evaluate_node(node.right)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.UnaryOp):
            operand = self._evaluate_node(node.operand)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](operand)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.Name):
            if node.id in self.variables:
                return self.variables[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

def validate_xml(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        if root.tag != 'calc':
            raise ValueError("Root element must be <calc>")
        for field in root.findall('field'):
            if 'name' not in field.attrib:
                raise ValueError("Each <field> must have a 'name' attribute")
            if field.text is None:
                raise ValueError("Each <field> must contain text")
        return root
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python renderer.py <xml_file>")
        sys.exit(1)

    xml_file = sys.argv[1]
    root = validate_xml(xml_file)

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if line:
            name, value = line.split('=')
            if not re.match(r'^[a-zA-Z]+$', name):
                raise ValueError(f"Invalid variable name: {name}")
            try:
                variables[name] = float(value)
            except ValueError:
                raise ValueError(f"Invalid value for {name}: {value}")

    evaluator = ExpressionEvaluator(variables)
    for field in root.findall('field'):
        name = field.get('name')
        expression = field.text.strip()
        try:
            result = evaluator.evaluate(expression)
            print(f"{name}={result}")
        except ValueError as e:
            print(f"Error evaluating {name}: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
