import secrets
import re
from pathlib import Path

def evaluate_expression(expression, context):
    allowed_names = {
        '__builtins__': None,
        '__name__': None,
        '__doc__': None,
        '__package__': None,
        '__loader__': None,
        '__spec__': None,
        '__annotations__': None,
        '__file__': None,
        '__cached__': None,
    }
    allowed_names.update(context)
    try:
        return eval(expression, {"__builtins__": None}, allowed_names)
    except Exception:
        return None

def sanitize_path(path):
    sanitized = Path(path).resolve()
    if not sanitized.is_absolute() or not sanitized.exists():
        raise ValueError("Invalid path")
    return sanitized

def main():
    recipe_file = sys.stdin.readline().strip()
    output_file = sys.stdin.readline().strip()

    try:
        recipe_file = sanitize_path(recipe_file)
        output_file = sanitize_path(output_file)
    except ValueError:
        print("error", file=sys.stderr)
        sys.exit(1)

    context = {}

    try:
        with open(recipe_file, 'r', encoding='utf-8') as f:
            for line in f:
                match = re.match(r'(\w+)\s*=\s*(.+)', line.strip())
                if match:
                    name, expression = match.groups()
                    result = evaluate_expression(expression, context)
                    if result is None:
                        print("error", file=sys.stderr)
                        sys.exit(1)
                    context[name] = result
    except FileNotFoundError:
        print("error", file=sys.stderr)
        sys.exit(1)
    except Exception:
        print("error", file=sys.stderr)
        sys.exit(1)

    run_id = secrets.token_hex(16)

    output = {
        "run_id": run_id,
        "results": context
    }

    try:
        with open(output_file, 'w', encoding='utf-8') as f:
