import sys
import re
import ast
import operator
import os

def evaluate_expression(expression, variables):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    def eval_node(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, int):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise NameError(f"Undefined variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise TypeError(f"Unsupported operation: {op_type}")
        else:
            raise TypeError(f"Unsupported node type: {type(node)}")

    try:
        parsed_expr = ast.parse(expression, mode='eval')
        return eval_node(parsed_expr.body)
    except Exception as e:
        raise e

def render_template(template, variables):
    pattern = re.compile(r'\{\{(.*?)\}\}')
    result = template
    log_entries = []

    for match in pattern.finditer(template):
        placeholder = match.group(0)
        expression = match.group(1).strip()
        try:
            result_value = evaluate_expression(expression, variables)
            result = result.replace(placeholder, str(result_value), 1)
            log_entries.append(f"{placeholder} -> {result_value}")
        except Exception as e:
            log_entries.append(f"{placeholder} ERROR {str(e)}")

    return result, log_entries

def main():
    if len(sys.argv) != 2:
        print("Usage: python render.py <template-file-path>")
        sys.exit(1)

    template_path = sys.argv[1]

    if not os.path.isfile(template_path):
        print("Error: Template file does not exist.")
        sys.exit(1)

    try:
        with open(template_path, 'r', encoding='utf-8') as file:
            template = file.read()
    except Exception as e:
        print(f"Error reading template file: {e}")
        sys.exit(1)

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            name, value = line.split('=', 1)
            if not re.match(r'^[A-Za-z_]\w*$', name):
                raise ValueError("Invalid variable name")
            variables[name] = int(value)
        except Exception as e:
            print(f"Error processing variable assignment: {e}")
            sys.exit(1)

    rendered_template, log_entries = render_template(template, variables)
    print(rendered_template)

    try:
        with open('render.log', 'w', encoding='utf-8') as log_file:
            for entry in log_entries:
                log_file.write(entry + '\n')
    except Exception as e:
        print(f"Error writing to log file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import time
import ast
import operator

class SafeEvaluator(ast.NodeVisitor):
    def __init__(self):
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
        }

    def evaluate(self, expression):
        try:
            tree = ast.parse(expression, mode='eval')
            return self.visit(tree.body)
        except (SyntaxError, TypeError, ZeroDivisionError):
            return "ERROR: invalid expression"

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        op_type = type(node.op)
        if op_type in self.operators:
            return self.operators[op_type](left, right)
        else:
            return "ERROR: unsupported operation"

    def visit_Num(self, node):
        return node.n

    def visit_Expr(self, node):
        return self.visit(node.value)

    def visit_Expression(self, node):
        return self.visit(node.body)

    def generic_visit(self, node):
        return "ERROR: invalid expression"

def evaluate_expression(expression):
    evaluator = SafeEvaluator()
    result = evaluator.evaluate(expression)
    if isinstance(result, (int, float)):
        if result.is_integer():
            return int(result)
        else:
            return f"{result:.2f}"
    return result

def sanitize_path(path):
    import os
    return os.path.normpath(os.path.abspath(path))

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py N", file=sys.stderr)
        sys.exit(1)

    try:
        N = int(sys.argv[1])
        if not (0 <= N <= 1000):
            raise ValueError
    except ValueError:
        print("N must be an integer between 0 and 1000", file=sys.stderr)
        sys.exit(1)

    file_path = sys.stdin.readline().strip()
    file_path = sanitize_path(file_path)

    try:
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if not line:
                    continue

                result = evaluate_expression(line)
                print(f"{line} = {result}")

                if N > 0:
                    count = 1
                    last_print_time = time.time()
                    while count % N != 0:
                        current_time = time.time()
                        if current_time - last_print_time >= 1:
                            break
                        time.sleep(0.1)
                    last_print_time = time.time()

    except IOError:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import time
import urllib.request
import ssl
from datetime import datetime, timezone
from urllib.parse import urlparse
import socket

def validate_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def fetch_urls(urls_file, out_dir, log_file, rate):
    if not os.path.exists(out_dir):
        os.makedirs(out_dir)

    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip() and validate_url(line.strip())]

    if not urls:
        print("No valid URLs found in the provided file.")
        return

    context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED

    with open(log_file, 'a', encoding='utf-8') as log:
        for i, url in enumerate(urls, start=1):
            try:
                req = urllib.request.Request(url, timeout=10)
                with urllib.request.urlopen(req, context=context) as response:
                    data = response.read(10 * 1024 * 1024)  # Limit to 10MB
                    if len(data) == 10 * 1024 * 1024:
                        raise Exception("Data size limit exceeded")
                    with open(os.path.join(out_dir, f"{i}.bin"), 'wb') as out_file:
                        out_file.write(data)
                    log.write(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')}\t{url}\tok\t{len(data)}\n")
            except (urllib.error.URLError, ssl.SSLError, socket.timeout) as e:
                log.write(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')}\t{url}\terror\t{str(e.reason) if hasattr(e, 'reason') else str(e)}\n")
            except Exception as e:
                log.write(f"{datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')}\t{url}\terror\t{str(e)}\n")
            if i < len(urls):
                time.sleep(max(1 / rate - (time.time() % (1 / rate)), 0))

if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: python fetch.py <urls_file> <out_dir> <log_file> <rate>")
        sys.exit(1)

    urls_file = sys.argv[1]
    out_dir = os.path.abspath(sys.argv[2])
    log_file = os.path.abspath(sys.argv[3])
    try:
        rate = int(sys.argv[4])
        if rate <= 0:
            raise ValueError
    except ValueError:
        print("Rate must be a positive integer.")
        sys.exit(1)

    if not os.path.isfile(urls_file):
        print("The specified URLs file does not exist.")
        sys.exit(1)

    if not os.path.isabs(out_dir) or not os.path.isabs(log_file):
        print("Output directory and log file must be absolute paths.")
        sys.exit(1)

    fetch_urls(urls_file, out_dir, log_file, rate)

import sys
import os
import sqlite3
import xml.etree.ElementTree as ET
import re

def read_cache(cache_path):
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as cache_file:
            for line in cache_file:
                print(line.strip())

def write_cache(cache_path, rows):
    with open(cache_path, 'w') as cache_file:
        for row in rows:
            cache_file.write('\t'.join(map(lambda x: '' if x is None else str(x), row)) + '\n')

def sanitize_path(base_path, relative_path):
    # Normalize the path to prevent path traversal
    normalized_path = os.path.normpath(os.path.join(base_path, relative_path))
    if not normalized_path.startswith(base_path):
        raise ValueError("Invalid path detected")
    return normalized_path

def run_query(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    database = sanitize_path(os.path.dirname(config_path), root.find('database').text)
    table = root.find('table').text

    # Validate table name to prevent SQL injection
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', table):
        raise ValueError("Invalid table name")

    conn = sqlite3.connect(database)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table}")
    rows = cursor.fetchall()
    conn.close()

    return rows

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py <config.xml> <cache_file>")
        sys.exit(1)

    config_path = sys.argv[1]
    cache_path = sys.argv[2]

    try:
        read_cache(cache_path)

        if not os.path.exists(cache_path):
            rows = run_query(config_path)
            write_cache(cache_path, rows)
            for row in rows:
                print('\t'.join(map(lambda x: '' if x is None else str(x), row)))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import sqlite3
import time
import os
from concurrent.futures import ThreadPoolExecutor, as_completed
from threading import Lock

def validate_spec_element(spec_element):
    if not isinstance(spec_element, dict):
        raise ValueError("Spec element must be a dictionary")
    if 'table' not in spec_element or not isinstance(spec_element['table'], str):
        raise ValueError("Spec element must have a valid 'table' key")
    if 'columns' not in spec_element or not isinstance(spec_element['columns'], list) or not all(isinstance(col, str) for col in spec_element['columns']):
        raise ValueError("Spec element must have a valid 'columns' key")
    if 'filters' not in spec_element or not isinstance(spec_element['filters'], dict):
        raise ValueError("Spec element must have a valid 'filters' key")
    if 'output' not in spec_element or not isinstance(spec_element['output'], str):
        raise ValueError("Spec element must have a valid 'output' key")

def validate_output_path(output_path):
    if not output_path or not isinstance(output_path, str):
        raise ValueError("Output path must be a valid string")
    if os.path.isabs(output_path) and not output_path.startswith('/tmp'):
        raise ValueError("Output path must be within a secure directory")

def process_spec_element(spec_element, db_path, lock):
    validate_spec_element(spec_element)
    validate_output_path(spec_element['output'])

    table = spec_element['table']
    columns = spec_element['columns']
    filters = spec_element['filters']
    output = spec_element['output']

    query = f"SELECT {', '.join(['?'] * len(columns))} FROM {table}"
    filter_conditions = " AND ".join([f"{col} = ?" for col in filters.keys()])
    query += f" WHERE {filter_conditions}" if filters else ""

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    try:
        if filters:
            cursor.execute(query, tuple(columns) + tuple(filters.values()))
        else:
            cursor.execute(query, tuple(columns))

        rows = cursor.fetchall()
        result = [dict(zip(columns, row)) for row in rows]

        with lock:
            with open(output, 'w') as f:
                json.dump(result, f)

        return {'output': output, 'rows': len(rows)}
    finally:
        conn.close()

def main(spec_path, db_path):
    with open(spec_path, 'r') as f:
        spec = json.load(f)

    if not isinstance(spec, list):
        raise ValueError("Spec file must contain a JSON array")

    results = []
    start_time = time.time()
    lock = Lock()
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for i, spec_element in enumerate(spec):
            if i > 0:
                elapsed = time.time() - start_time
                if elapsed < i / 4:
                    time.sleep(i / 4 - elapsed)
            futures.append(executor.submit(process_spec_element, spec_element, db_path, lock))

        for future in as_completed(futures):
            results.append(future.result())

    print(json.dumps(results))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python export_rows.py <spec.json> <database.db>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

import sys
import sqlite3
import json
import ast
import signal
from contextlib import contextmanager

# Timeout context manager
@contextmanager
def time_limit(seconds):
    def signal_handler(signum, frame):
        raise TimeoutError("Operation timed out")
    signal.signal(signal.SIGALRM, signal_handler)
    signal.alarm(seconds)
    try:
        yield
    finally:
        signal.alarm(0)

# Safe eval function
def safe_eval(condition, context):
    try:
        tree = ast.parse(condition, mode='eval')
        return eval(compile(tree, filename="<ast>", mode="eval"), {"__builtins__": {}}, context)
    except Exception:
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python access_check.py <database_file>")
        return

    db_path = sys.argv[1]
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        try:
            token, resource, context_json = line.split('\t')
        except ValueError:
            print("DENY invalid_input")
            continue

        try:
            ctx = json.loads(context_json)
        except json.JSONDecodeError:
            print("DENY invalid_json")
            continue

        cursor.execute("SELECT user FROM tokens WHERE token = ?", (token,))
        token_row = cursor.fetchone()

        if not token_row:
            print("DENY no_token")
            continue

        user = token_row[0]
        cursor.execute("""
            SELECT id, condition FROM rules
            WHERE user = ? AND resource = ?
            ORDER BY id ASC
            LIMIT 1
        """, (user, resource))
        rule_row = cursor.fetchone()

        if not rule_row:
            print("DENY no_rule")
            continue

        rule_id, condition = rule_row
        try:
            with time_limit(1):  # 1 second timeout
                if safe_eval(condition, {"user": user, "resource": resource, "ctx": ctx}):
                    print(f"ALLOW {rule_id}")
                else:
                    print("DENY condition_false")
        except TimeoutError:
            print("DENY timeout")
        except Exception:
            print("DENY condition_false")

    conn.close()

if __name__ == "__main__":
    main()

import sys
import json
import sqlite3
import argparse
from contextlib import closing

def validate_input(data):
    if not isinstance(data.get('token_id'), str) or not data['token_id']:
        raise ValueError("Invalid token_id")
    if not isinstance(data.get('cost'), int) or data['cost'] < 0:
        raise ValueError("Invalid cost")
    if data.get('category') is not None and not isinstance(data['category'], str):
        raise ValueError("Invalid category")

def main():
    parser = argparse.ArgumentParser(description='Process JSON Lines for quota query.')
    parser.add_argument('--db', required=True, help='Path to the SQLite database file.')
    args = parser.parse_args()

    with closing(sqlite3.connect(args.db)) as conn:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()

        for line in sys.stdin:
            try:
                data = json.loads(line.strip())
                validate_input(data)

                token_id = data['token_id']
                cost = data['cost']
                category = data.get('category')

                cursor.execute('SELECT credits, enabled FROM tokens WHERE token_id = ?', (token_id,))
                token = cursor.fetchone()

                if not token or token['enabled'] == 0 or token['credits'] < cost:
                    print(json.dumps({"status": "denied"}))
                    continue

                new_credits = token['credits'] - cost
                cursor.execute('UPDATE tokens SET credits = ? WHERE token_id = ?', (new_credits, token_id))

                if category is not None:
                    cursor.execute('SELECT id, title, category FROM items WHERE category = ? ORDER BY id ASC', (category,))
                else:
                    cursor.execute('SELECT id, title, category FROM items ORDER BY id ASC')

                rows = cursor.fetchall()
                result = {"status": "ok", "rows": [{"id": row['id'], "title": row['title'], "category": row['category']} for row in rows]}
                print(json.dumps(result))

                conn.commit()
            except json.JSONDecodeError:
                print(json.dumps({"status": "error", "message": "Invalid JSON"}))
            except ValueError as ve:
                print(json.dumps({"status": "error", "message": str(ve)}))
            except sqlite3.Error as e:
                print(json.dumps({"status": "error", "message": "Database error"}))
            except Exception as e:
                print(json.dumps({"status": "error", "message": "An unexpected error occurred"}))

