import sys
import xml.etree.ElementTree as ET
import sqlite3
import re
import ast
import operator

def parse_config(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    table = root.get('table')
    columns = []
    for column in root.findall('column'):
        columns.append({
            'name': column.get('name'),
            'source': column.get('source')
        })
    return table, columns

def evaluate_expression(expression, row):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Name: lambda: row.get(node.id, 'NULL'),
        ast.Num: lambda: node.n,
        ast.Expression: lambda: eval_node(node.body)
    }

    def eval_node(node):
        if type(node) in allowed_operators:
            return allowed_operators[type(node)]()
        else:
            raise ValueError("Unsupported operation")

    try:
        tree = ast.parse(expression, mode='eval')
        return eval_node(tree.body)
    except Exception:
        return 'NULL'

def main(config_file, db_file):
    table, columns = parse_config(config_file)

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    cursor.execute("PRAGMA table_info(?)", (table,))
    column_names = [info[1] for info in cursor.fetchall()]

    print(','.join(column['name'] for column in columns))

    cursor.execute("SELECT * FROM ?", (table,))
    for row in cursor.fetchall():
        row_dict = dict(zip(column_names, row))
        output = []
        for column in columns:
            if column['source'] in column_names:
                value = row_dict[column['source']]
            else:
                value = evaluate_expression(column['source'], row_dict)
            if value is None:
                value = ''
            elif isinstance(value, (int, float)):
                value = f"{value:.10g}"
            else:
                value = str(value)
                if any(c in value for c in [',', '"', '\n']):
                    value = '"' + value.replace('"', '""') + '"'
            output.append(value)
        print(','.join(output))

    conn.close()

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

import sys
import xml.etree.ElementTree as ET
import sqlite3
import json
import concurrent.futures
import os
import re

def sanitize_query(query_text):
    # Basic sanitation to prevent SQL injection
    if not re.match(r'^SELECT\s+.*$', query_text, re.IGNORECASE):
        raise ValueError("Invalid query format")
    return query_text

def sanitize_id(query_id):
    # Basic sanitation to prevent injection in query IDs
    if not re.match(r'^[a-zA-Z0-9_-]+$', query_id):
        raise ValueError("Invalid query ID")
    return query_id

def sanitize_db_path(db_path):
    # Prevent path traversal by ensuring the path is absolute and within a safe directory
    safe_root = '/safe/db/directory'
    abs_path = os.path.abspath(db_path)
    if not abs_path.startswith(safe_root):
        raise ValueError("Invalid database path")
    return abs_path

def execute_query(db_path, query_id, query_text):
    try:
        sanitized_query = sanitize_query(query_text)
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(sanitized_query)
            row_count = len(cursor.fetchall())
            return {"id": sanitize_id(query_id), "row_count": row_count}
    except Exception as e:
        return {"id": sanitize_id(query_id), "error": "An error occurred"}

def main(config_file):
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        db_path = sanitize_db_path(root.get('db'))
        max_parallel = int(root.get('max_parallel'))
        if max_parallel <= 0:
            raise ValueError("max_parallel must be a positive integer")

        queries = [(query.get('id'), query.text) for query in root.findall('query')]

        with concurrent.futures.ThreadPoolExecutor(max_workers=max_parallel) as executor:
            futures = [executor.submit(execute_query, db_path, query_id, query_text) for query_id, query_text in queries]
            for future in concurrent.futures.as_completed(futures):
                print(json.dumps(future.result()))

    except ET.ParseError:
        print(json.dumps({"error": "Malformed XML"}))
    except Exception as e:
        print(json.dumps({"error": str(e)}))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(json.dumps({"error": "Usage: python run_queries.py config.xml"}))
    else:
        main(sys.argv[1])

import sys
import sqlite3
import re
import ast
import operator

def evaluate_expression(expression, row):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    def eval_expr(node):
        if isinstance(node, ast.BinOp):
            left = eval_expr(node.left)
            right = eval_expr(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            return float(row[node.id])
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    tree = ast.parse(expression, mode='eval')
    return str(eval_expr(tree.body))

def main():
    if len(sys.argv) < 3:
        print("Usage: python report.py <database> <table> [column=value]", file=sys.stderr)
        sys.exit(1)

    db_path, table_name = sys.argv[1], sys.argv[2]
    filter_column, filter_value = None, None

    if len(sys.argv) == 4:
        filter_column, filter_value = sys.argv[3].split('=', 1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
        if not cursor.fetchone():
            raise ValueError(f"Table {table_name} does not exist in the database.")

        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [col[1] for col in cursor.fetchall()]

        query = f"SELECT * FROM {table_name}"
        params = ()
        if filter_column:
            if filter_column not in columns:
                raise ValueError(f"Column {filter_column} does not exist in the table.")
            query += f" WHERE {filter_column} = ?"
            params = (filter_value,)

        cursor.execute(query, params)
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        conn.close()

    template = sys.stdin.read()

    for row in rows:
        row_dict = dict(zip(columns, row))
        rendered_html = re.sub(r'{{(.*?)}}', lambda m: evaluate_expression(m.group(1), row_dict), template)
        print(rendered_html)

if __name__ == "__main__":
    main()

import sqlite3
import time
import os
import html
import re

def read_terms(file_path):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File {file_path} not found.")
    with open(file_path, 'r') as file:
        return [line.strip() for line in file.readlines() if line.strip()]

def query_database(term, db_path):
    if not os.path.isfile(db_path):
        raise FileNotFoundError(f"Database file {db_path} not found.")
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    query = "SELECT id, name, price, stock FROM items WHERE name LIKE ?"
    cursor.execute(query, ('%' + term + '%',))
    results = cursor.fetchall()
    conn.close()
    return results

def escape_html(text):
    return html.escape(text)

def write_html_report(results, terms, output_path):
    with open(output_path, 'w') as file:
        file.write('<table>\n')
        file.write('<tr><th>Term</th><th>ID</th><th>Name</th><th>Price</th><th>Stock</th></tr>\n')
        for term in terms:
            for row in results[term]:
                file.write(f'<tr><td>{escape_html(term)}</td><td>{escape_html(str(row[0]))}</td><td>{escape_html(row[1])}</td><td>{escape_html(str(row[2]))}</td><td>{escape_html(str(row[3]))}</td></tr>\n')
        file.write('</table>')

def main():
    terms_file = 'terms.txt'
    db_file = 'data.db'
    report_file = 'report.html'

    try:
        terms = read_terms(terms_file)
        results = {}

        start_time = time.time()
        query_count = 0

        for term in terms:
            if query_count >= 5:
                elapsed = time.time() - start_time
                if elapsed < 1:
                    time.sleep(1 - elapsed)
                start_time = time.time()
                query_count = 0

            results[term] = query_database(term, db_file)
            query_count += 1

        write_html_report(results, terms, report_file)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == '__main__':
    main()

