import operator

def parse_where(where):
    match = re.match(r'(\w+)\s*=\s*(.+)', where)
    if not match:
        raise ValueError("Invalid WHERE clause")
    column, value = match.groups()
    if value.startswith("'") and value.endswith("'"):
        value = value[1:-1]
    else:
        try:
            value = float(value)
        except ValueError:
            raise ValueError("Invalid literal in WHERE clause")
    return column, value

def safe_eval(node, allowed_names):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body, allowed_names)
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left, allowed_names)
        right = safe_eval(node.right, allowed_names)
        op = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv
        }.get(type(node.op))
        if op is None:
            raise ValueError("Unsupported operation")
        return op(left, right)
    elif isinstance(node, ast.Name):
        if node.id not in allowed_names:
            raise ValueError(f"Use of disallowed name '{node.id}'")
        return allowed_names[node.id]
    elif isinstance(node, ast.Num):
        return node.n
    else:
        raise ValueError("Unsupported expression")

def evaluate_formula(formula, row):
    try:
        tree = ast.parse(formula, mode='eval')
        return safe_eval(tree, row)
    except Exception as e:
        raise ValueError(f"Invalid formula: {str(e)}")

def main():
    if len(sys.argv) != 5 or sys.argv[2] != '--where' or sys.argv[4] != '--formula':
        print("Usage: python filter_sales.py db_path --where VALUE --formula VALUE", file=sys.stderr)
        sys.exit(1)

    db_path, where, formula = sys.argv[1], sys.argv[3], sys.argv[5]

    try:
        column, value = parse_where(where)
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='sales'")
        if cursor.fetchone() is None:
            raise ValueError("Table 'sales' does not exist")

        cursor.execute(f"SELECT id, region, amount FROM sales WHERE {column} = ?", (value,))
        rows = cursor.fetchall()

        writer = csv.writer(sys.stdout)
        writer.writerow(['id', 'region', 'computed'])

        for row in rows:
            row_dict = {'id': row[0], 'region': row[1], 'amount': row[2]}
            computed = evaluate_formula(formula, row_dict)
            writer.writerow([row[0], row[1], f"{computed:.2f}"])

        conn.close()

        timestamp = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        with open('query.log', 'a') as log:
            log.write(f"{timestamp} | OK | {len(rows)}\n")

        sys.exit(0)

    except Exception as e:
        timestamp = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        with open('query.log', 'a') as log:
            log.write(f"{timestamp} | ERROR | {str(e)}\n")

        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import time
import sqlite3
import ast
import operator
import re

def evaluate_expression(expression, row_values):
    operators = {
        ast.Add: operator.add
    }

    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            if node.id not in row_values:
                raise ValueError(f"Invalid column name: {node.id}")
            return row_values[node.id]
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def sanitize_table_name(name):
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        raise ValueError("Invalid table name")
    return name

def sanitize_column_names(names):
    sanitized = []
    for name in names:
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            raise ValueError(f"Invalid column name: {name}")
        sanitized.append(name)
    return sanitized

def main():
    if len(sys.argv) != 4:
        print("Usage: python apply_rules.py rules.txt data.sqlite3 --max-rows-per-second N")
        sys.exit(1)

    rules_file = sys.argv[1]
    db_file = sys.argv[2]
    max_rows_per_second = int(sys.argv[3])

    if max_rows_per_second <= 0:
        print("Error: max_rows_per_second must be greater than 0")
        sys.exit(1)

    try:
        with open(rules_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except IOError:
        print("Error: Unable to read the rules file")
        sys.exit(1)

    if len(lines) < 2:
        print("Error: Rules file must contain at least two lines")
        sys.exit(1)

    table_name = sanitize_table_name(lines[0].strip())
    columns = sanitize_column_names(lines[1].strip().split(','))
    rules = [line.strip().split('\t') for line in lines[2:] if line.strip()]

    if not rules:
        print("Error: No rules found in the rules file")
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
    except sqlite3.Error:
        print("Error: Unable to connect to the database")
        sys.exit(1)

    try:
        query = f"SELECT {', '.join(columns)} FROM {table_name}"
        cursor.execute(query)
    except sqlite3.Error:
        print("Error: Unable to execute the query")
        sys.exit(1)

    rule_counts = {rule[0]: 0 for rule in rules}
    last_read_time = time.time()

    try:
        for row in cursor:
            row_values = dict(zip(columns, row))
            for rule_name, expression in rules:
                try:
                    if evaluate_expression(expression, row_values) > 0:
                        rule_counts[rule_name] += 1
                except ValueError:
                    print(f"Error: Invalid expression for rule '{rule_name}'")
                    sys.exit(1)

            current_time = time.time()
            elapsed_time = current_time - last_read_time
            if elapsed_time < 1 / max_rows_per_second:
                time.sleep(1 / max_rows_per_second - elapsed_time)
            last_read_time = time.time()
    except KeyboardInterrupt:
        pass
    finally:
        conn.close()

    for rule_name, count in rule_counts.items():
        print(f"{rule_name}\t{count}")

if __name__ == "__main__":
    main()

import sys
import json
import sqlite3
import time
from collections import deque

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python inventory_report.py <database_file>\n")
        sys.exit(1)

    db_path = sys.argv[1]
    query_times = deque()
    query_failed = False

    for line_number, line in enumerate(sys.stdin, start=1):
        line = line.strip()
        if not line:
            continue

        try:
            query_data = json.loads(line)
        except json.JSONDecodeError:
            sys.stderr.write(f"ERROR {line_number}\n")
            continue

        # Validate JSON keys and values
        valid_keys = {"id", "name", "quantity", "price"}
        if not all(key in valid_keys for key in query_data.keys()):
            sys.stderr.write(f"ERROR {line_number}\n")
            continue

        while len(query_times) >= 3 and time.time() - query_times[0] < 1:
            time.sleep(0.1)

        query_times.append(time.time())
        if len(query_times) > 3:
            query_times.popleft()

        sys.stderr.write(f"INFO start {line_number}\n")

        try:
            with sqlite3.connect(db_path, timeout=5) as conn:
                cursor = conn.cursor()
                query = "SELECT id, name, quantity, price FROM items WHERE " + " AND ".join(
                    f"{key} = ?" for key in query_data.keys()
                )
                cursor.execute(query, tuple(query_data.values()))
                rows = cursor.fetchall()

                for row in rows:
                    print(json.dumps(dict(zip(["id", "name", "quantity", "price"], row))))

                sys.stderr.write(f"INFO done {line_number} {len(rows)}\n")
        except sqlite3.Error:
            sys.stderr.write(f"ERROR {line_number}\n")
            query_failed = True

    if query_failed:
        sys.exit(1)
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import json
import hashlib
import urllib.request
import ssl
import re
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def fetch_url(url, timeout=10):
    context = ssl.create_default_context()
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    try:
        with urllib.request.urlopen(url, timeout=timeout, context=context) as response:
            return response.read()
    except (urllib.error.URLError, ssl.SSLError) as e:
        print(f"Error fetching {url}: {e}", file=sys.stderr)
        return None

def main():
    cache_file = 'cache.json'
    try:
        with open(cache_file, 'r') as f:
            cache = json.load(f)
    except FileNotFoundError:
        cache = {}

    urls = sys.stdin.read().strip().split('\n')
    output = []

    for url in urls:
        if not is_valid_url(url):
            print(f"Invalid URL: {url}", file=sys.stderr)
            continue

        if url in cache:
            hexstring = cache[url]
        else:
            body = fetch_url(url)
            if body is None:
                continue
            hexstring = hashlib.sha256(body).hexdigest()
            cache[url] = hexstring
        output.append(f"{url},{hexstring}")

    print('\n'.join(output))

    with open(cache_file, 'w') as f:
        json.dump(cache, f)

if __name__ == '__main__':
    main()

import json
import os
import requests
from urllib.parse import urlparse, urljoin
from html import escape

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_html(text):
    return escape(text)

def main():
    try:
        with open('feeds.json', 'r') as file:
            feeds = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError, KeyError, TypeError):
        html_content = "<h2>Error</h2><p>Invalid feeds.json file</p>"
        with open('report.html', 'w') as file:
            file.write(html_content)
        return

    if not isinstance(feeds, list) or len(feeds) == 0:
        html_content = "<h2>Error</h2><p>Invalid feeds.json content</p>"
        with open('report.html', 'w') as file:
            file.write(html_content)
        return

    feed = feeds[0]
    if 'name' not in feed or 'url' not in feed:
        html_content = "<h2>Error</h2><p>Invalid feed object</p>"
        with open('report.html', 'w') as file:
            file.write(html_content)
        return

    name = sanitize_html(feed['name'])
    url = feed['url']

    if not is_valid_url(url):
        html_content = f"<h2>{name}</h2><p>Invalid URL</p>"
        with open('report.html', 'w') as file:
            file.write(html_content)
        return

    try:
        response = requests.get(url, verify=True)
    except requests.RequestException:
        html_content = f"<h2>{name}</h2><p>unavailable</p>"
        with open('report.html', 'w') as file:
            file.write(html_content)
        return

    if response.status_code == 200:
        try:
            data = response.json()
            if not isinstance(data, dict) or 'title' not in data or 'items' not in data:
                raise ValueError

            title = sanitize_html(data['title'])
            items = data['items'][:3]

            html_content = f"<h2>{name}</h2><p>{title}</p><ul>"
            for item in items:
                if 'headline' in item and 'link' in item:
                    headline = sanitize_html(item['headline'])
                    link = urljoin(url, item['link'])
                    html_content += f"<li><a href='{link}'>{headline}</a></li>"
            html_content += "</ul>"
        except (KeyError, ValueError):
            html_content = f"<h2>{name}</h2><p>unavailable</p>"
    else:
        html_content = f"<h2>{name}</h2><p>unavailable</p>"

    try:
        with open('report.html', 'w') as file:
            file.write(html_content)
    except IOError:
        pass

if __name__ == "__main__":
    main()

import sys
import json
import requests
from requests.exceptions import RequestException
import re

def validate_expression(expression):
    # Only allow simple mathematical and dictionary access operations
    if not re.match(r"^[\w\[\]\'\"\s\+\-\*/\(\)]+$", expression):
        raise ValueError("Invalid characters in expression")

def main():
    config_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error reading configuration file: {e}", file=sys.stderr)
        sys.exit(1)

    results = {}

    for url, expression in config.items():
        try:
            validate_expression(expression)
        except ValueError as e:
            print(f"Invalid expression for URL {url}: {e}", file=sys.stderr)
            continue

        try:
            response = requests.get(url, timeout=10, verify=True)
            response.raise_for_status()
            response_data = response.json()
        except (RequestException, json.JSONDecodeError) as e:
            print(f"Error fetching or parsing data from {url}: {e}", file=sys.stderr)
            continue

        evaluated_values = []
        for item in response_data:
            try:
                evaluated_value = eval(expression, {"item": item})
                if not isinstance(evaluated_value, int):
                    raise ValueError("Expression did not evaluate to an integer")
                evaluated_values.append(evaluated_value)
            except Exception as e:
                print(f"Error evaluating expression for item {item}: {e}", file=sys.stderr)
                continue

        results[url] = evaluated_values

    try:
        with open(output_path, 'w') as output_file:
            json.dump(results, output_file)
    except IOError as e:
        print(f"Error writing to output file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import time
import json
import urllib.request
from datetime import datetime, timedelta
import ssl
import re

CACHE_FILE = os.path.expanduser('~/.repo_cache.dat')

def log_message(message):
    print(f"{datetime.utcnow().isoformat()} {message}", file=sys.stderr)

def fetch_repo_data(owner, repo):
    url = f"https://api.github.com/repos/{owner}/{repo}"
    context = ssl.create_default_context()
    try:
        with urllib.request.urlopen(url, context=context) as response:
            data = json.loads(response.read().decode())
            return data.get('full_name'), data.get('stargazers_count')
    except (urllib.error.URLError, json.JSONDecodeError, KeyError):
        return None, None

def load_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, 'r') as f:
            return json.load(f)
    return None

def save_cache(identifier, fetch_time, full_name, stargazers_count):
    cache_data = {
        'identifier': identifier,
        'fetch_time': fetch_time,
        'full_name': full_name,
        'stargazers_count': stargazers_count
    }
    with open(CACHE_FILE, 'w') as f:
        json.dump(cache_data, f)

def is_valid_identifier(identifier):
    return re.match(r'^[a-zA-Z0-9-]+/[a-zA-Z0-9-]+$', identifier) is not None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    identifier = sys.argv[1]
    if not is_valid_identifier(identifier):
        log_message("fetch failure")
        sys.exit(1)

    cache = load_cache()

    if cache and cache['identifier'] == identifier:
        fetch_time = datetime.fromisoformat(cache['fetch_time'])
        if datetime.utcnow() - fetch_time < timedelta(hours=24):
            print(f"{cache['full_name']} {cache['stargazers_count']}")
            log_message("cache hit")
            sys.exit(0)

    full_name, stargazers_count = fetch_repo_data(*identifier.split('/'))
    if full_name is None or stargazers_count is None:
        log_message("fetch failure")
        sys.exit(1)

    print(f"{full_name} {stargazers_count}")
    save_cache(identifier, datetime.utcnow().isoformat(), full_name, stargazers_count)
    log_message("cache miss")
    sys.exit(0)

if __name__ == "__main__":
    main()

import os
import sys
import xml.etree.ElementTree as ET
import json
import xml.sax.saxutils as saxutils

def load_config():
    cache_file = 'auth.cache'
    xml_file = 'auth.xml'

    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return json.load(f)

    if not os.path.exists(xml_file):
        sys.exit(1)

    # Use defusedxml to prevent XXE attacks
    try:
        import defusedxml.ElementTree as ET
    except ImportError:
        sys.exit("defusedxml library is required to run this script securely.")

    tree = ET.parse(xml_file)
    root = tree.getroot()

    config = []
    for user in root.findall('user'):
        name = user.get('name')
        token = user.find('token').text
        allows = [allow.get('action') for allow in user.findall('allow')]
        config.append({'name': name, 'token': token, 'allows': allows})

    with open(cache_file, 'w') as f:
        json.dump(config, f)

    return config

def validate_input(data):
    if not isinstance(data, dict):
        return False
    if 'token' not in data or 'action' not in data:
        return False
    if not isinstance(data['token'], str) or not isinstance(data['action'], str):
        return False
    return True

def main():
    config = load_config()
    try:
        input_data = json.load(sys.stdin)
    except json.JSONDecodeError:
        sys.exit(1)

    if not validate_input(input_data):
        sys.exit(1)

    token = input_data['token']
    action = input_data['action']

    for user in config:
        if user['token'] == token and action in user['allows']:
            print(f"ok {saxutils.escape(user['name'])}")
            sys.exit(0)

    print("denied")
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import re
import xml.etree.ElementTree as ET
import pickle
import os
import ast
import hashlib

def safe_eval(expr):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expr, mode='eval')
        # Define allowed operations
        allowed_operations = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Num,
                              ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv,
                              ast.USub, ast.UAdd)
        # Check if the AST is composed of allowed operations
        for node in ast.walk(tree):
            if not isinstance(node, allowed_operations):
                raise ValueError("Invalid operation in expression")
        # Evaluate the expression safely
        return eval(compile(tree, '<string>', 'eval'))
    except Exception as e:
        print(f"Error evaluating expression '{expr}': {e}")
        return None

def process_xml(input_path, output_path, cache):
    tree = ET.parse(input_path)
    root = tree.getroot()
    total_replacements = 0
    cache_hits = 0

    def replace_placeholders(element):
        nonlocal total_replacements, cache_hits
        if element.text:
            matches = re.findall(r'{{\s*(.*?)\s*}}', element.text)
            for match in matches:
                stripped_expr = match.strip()
                if stripped_expr in cache:
                    replacement = str(cache[stripped_expr])
                    cache_hits += 1
                else:
                    result = safe_eval(stripped_expr)
                    if result is not None:
                        cache[stripped_expr] = result
                        replacement = str(result)
                    else:
                        replacement = match
                element.text = element.text.replace(f'{{{{ {match} }}}}', replacement)
                total_replacements += 1
        for child in element:
            replace_placeholders(child)

    replace_placeholders(root)
    tree.write(output_path, encoding='utf-8', xml_declaration=True)
    return total_replacements, cache_hits

def main():
    if len(sys.argv) != 3:
        print("Usage: python expand.py <input_xml> <output_xml>")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]
    cache_path = os.path.join(os.path.dirname(input_path), hashlib.md5(input_path.encode()).hexdigest() + '.expandcache')

    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as cache_file:
            cache = pickle.load(cache_file)
    else:
        cache = {}

    total_replacements, cache_hits = process_xml(input_path, output_path, cache)

    with open(cache_path, 'wb') as cache_file:
        pickle.dump(cache, cache_file)

    print(f"Replaced {total_replacements} placeholders ({cache_hits} from cache).")

if __name__ == "__main__":
    main()

import sys
import time
import os
from collections import defaultdict

def read_config(config_file):
    with open(config_file, 'r') as f:
        lines = f.readlines()
    if not lines or not lines[0].startswith('interval_ms '):
        raise ValueError("Invalid config file format")
    try:
        interval_ms = int(lines[0].split()[1])
        if interval_ms <= 0:
            raise ValueError("interval_ms must be a positive integer")
    except ValueError:
        raise ValueError("Invalid interval_ms value")

    nodes = {}
    for line in lines[1:]:
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("Invalid node configuration")
        name, capacity = parts
        try:
            capacity = int(capacity)
            if capacity < 0:
                raise ValueError("Node capacity must be non-negative")
        except ValueError:
            raise ValueError("Invalid node capacity")
        nodes[name] = capacity
    return interval_ms, nodes

def read_jobs(jobs_file):
    with open(jobs_file, 'r') as f:
        return [line.strip() for line in f if line.strip()]

def read_cache(cache_file):
    assignments = {}
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            for line in f:
                parts = line.split()
                if len(parts) != 2:
                    raise ValueError("Invalid cache file format")
                job_id, node_name = parts
                assignments[job_id] = node_name
    return assignments

def write_cache(cache_file, assignments):
    with open(cache_file, 'w') as f:
        for job_id, node_name in assignments.items():
            f.write(f"{job_id} {node_name}\n")

def sanitize_path(path):
    return os.path.normpath(os.path.abspath(path))

def main():
    if len(sys.argv) != 4:
        print("Usage: python assign_jobs.py config.txt jobs.txt assignments.cache")
        sys.exit(1)

    config_file, jobs_file, cache_file = map(sanitize_path, sys.argv[1:])

    try:
        interval_ms, nodes = read_config(config_file)
        jobs = read_jobs(jobs_file)
        assignments = read_cache(cache_file)
    except (IOError, ValueError) as e:
        print(f"Error reading input files: {e}")
        sys.exit(1)

    node_capacities = defaultdict(int)
    for node, capacity in nodes.items():
        node_capacities[node] = capacity

    for job_id in jobs:
        if job_id in assignments:
            print(f"{job_id} {assignments[job_id]}")
            continue

        assigned = False
        for node, capacity in nodes.items():
            if node_capacities[node] > 0:
                assignments[job_id] = node
                node_capacities[node] -= 1
                print(f"{job_id} {node}")
                assigned = True
                break

        if not assigned:
            break

        # Constant time delay to avoid timing attacks
        time.sleep(0.001)

    try:
        write_cache(cache_file, assignments)
    except IOError as e:
        print(f"Error writing to cache file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import time
import hashlib
import json
import errno

def is_valid_directory(path):
    return os.path.isdir(path) and os.access(path, os.R_OK)

def is_valid_file(path):
    return os.path.isfile(path) and os.access(path, os.R_OK)

def compute_cache_key(file_path):
    try:
        with open(file_path, 'rb') as f:
            file_bytes = f.read()
        return hashlib.sha256(file_bytes).hexdigest()
    except (IOError, OSError) as e:
        print(f"Error reading file {file_path}: {e}", file=sys.stderr)
        sys.exit(1)

def process_files(input_dir, cache_dir, max_per_second):
    if not is_valid_directory(input_dir) or not is_valid_directory(cache_dir):
        print("Invalid input or cache directory.", file=sys.stderr)
        sys.exit(1)

    if max_per_second <= 0:
        print("max_per_second must be a positive integer.", file=sys.stderr)
        sys.exit(1)

    files = sorted(f for f in os.listdir(input_dir) if is_valid_file(os.path.join(input_dir, f)))
    last_computation_time = 0

    for filename in files:
        file_path = os.path.join(input_dir, filename)
        cache_key = compute_cache_key(file_path)
        cache_file_path = os.path.join(cache_dir, f"{cache_key}.json")

        try:
            if os.path.exists(cache_file_path):
                with open(cache_file_path, 'r') as cache_file:
                    result = json.load(cache_file).get('result')
                print(f"{filename} cached")
            else:
                current_time = time.time()
                time_since_last_computation = current_time - last_computation_time
                if time_since_last_computation < 1 / max_per_second:
                    time.sleep(1 / max_per_second - time_since_last_computation)
                result = os.path.getsize(file_path)
                with open(cache_file_path, 'w') as cache_file:
                    json.dump({'result': result}, cache_file)
                print(f"{filename} computed")
                last_computation_time = time.time()
        except (IOError, OSError, json.JSONDecodeError) as e:
            print(f"Error processing file {filename}: {e}", file=sys.stderr)
            continue

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python throttled_cache.py <input_dir> <cache_dir> <max_per_second>", file=sys.stderr)
        sys.exit(1)

    input_dir = sys.argv[1]
    cache_dir = sys.argv[2]
    try:
        max_per_second = int(sys.argv[3])
    except ValueError:
        print("max_per_second must be an integer.", file=sys.stderr)
        sys.exit(1)

    process_files(input_dir, cache_dir, max_per_second)

import sys
import json
import re
import ast
import operator

def evaluate_expression(expression, data):
    # Define allowed operations
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    # Define a node visitor to evaluate the expression
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_Num(self, node):
            return node.n

        def visit_Name(self, node):
            if node.id in data:
                return data[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operation: {op_type}")

        def visit_Expression(self, node):
            return self.visit(node.body)

    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression syntax")

    # Evaluate the AST
    evaluator = ExpressionEvaluator()
    result = evaluator.visit(tree.body)

    # Format the result to two decimal places
    return f"{result:.2f}"

def main():
    if len(sys.argv) != 4:
        print("Usage: python report_tool.py <data.json> <template.html> <out.html>")
        return

    data_file_path = sys.argv[1]
    template_file_path = sys.argv[2]
    output_file_path = sys.argv[3]

    # Step 1: Read JSON data and write to cache file
    try:
        with open(data_file_path, 'r') as data_file:
            data = json.load(data_file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading data file: {e}")
        return

    cache_file_path = data_file_path + '.cache'
    try:
        with open(cache_file_path, 'w') as cache_file:
            json.dump(data, cache_file)
    except IOError as e:
        print(f"Error writing cache file: {e}")
        return

    # Step 2: Read template and replace placeholders
    try:
        with open(template_file_path, 'r') as template_file:
            template_content = template_file.read()
    except FileNotFoundError as e:
        print(f"Error reading template file: {e}")
        return

    # Find all placeholders and replace them with evaluated expressions
    def replace_placeholder(match):
        expression = match.group(1)
        try:
            return evaluate_expression(expression, data)
        except ValueError as e:
            print(f"Error evaluating expression: {e}")
            return match.group(0)  # Return the original placeholder on error

    result_content = re.sub(r'{{=(.*?)}}', replace_placeholder, template_content)

    # Write the result to the output HTML file
    try:
        with open(output_file_path, 'w') as output_file:
            output_file.write(result_content)
    except IOError as e:
        print(f"Error writing output file: {e}")
        return

if __name__ == "__main__":
    main()

import os
import json
import time
import subprocess
import pickle
from html import escape
import hashlib
import hmac
import base64

SECRET_KEY = b'secret_key'  # Replace with a secure secret key

def load_cache(cache_path):
    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as f:
            data = f.read()
            if hmac.compare_digest(verify_data(data), 'valid'):
                return pickle.loads(data[len(SECRET_KEY):])
    return {}

def save_cache(cache_path, cache):
    data = pickle.dumps(cache)
    signed_data = SECRET_KEY + data
    with open(cache_path, 'wb') as f:
        f.write(sign_data(signed_data))

def sign_data(data):
    return base64.b64encode(hmac.new(SECRET_KEY, data, hashlib.sha256).digest())

def verify_data(data):
    try:
        return hmac.compare_digest(sign_data(data[len(SECRET_KEY):]), data[:len(SECRET_KEY)])
    except:
        return False

def run_command(command):
    process = subprocess.Popen(command, shell=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.communicate()
    return stdout.decode() + stderr.decode(), process.returncode

def main():
    jobs_path = 'jobs.jsonl'
    cache_path = 'cache.bin'
    report_path = 'report.html'

    if not os.path.exists(jobs_path):
        print(f"Error: {jobs_path} does not exist.")
        return

    cache = load_cache(cache_path)
    jobs = []

    try:
        with open(jobs_path, 'r') as f:
            for line in f:
                job = json.loads(line)
                if 'name' in job and 'command' in job:
                    jobs.append(job)
                else:
                    print(f"Warning: Invalid job format: {job}")
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in {jobs_path}: {e}")
        return

    run_count = 0
    reuse_count = 0

    for job in jobs:
        name = job['name']
        command = job['command']
        cache_key = (name, command)

        if cache_key in cache:
            output, exit_status = cache[cache_key]
            reuse_count += 1
        else:
            time.sleep(0.25)
            output, exit_status = run_command(command)
            cache[cache_key] = (output, exit_status)
            run_count += 1

    save_cache(cache_path, cache)

    try:
        with open(report_path, 'w') as f:
            f.write(f'Ran: {run_count}, Reused: {reuse_count}<br><table border="1"><tr><th>Name</th><th>Exit Status</th><th>Output</th></tr>')
            for job in jobs:
                name = job['name']
                command = job['command']
                cache_key = (name, command)
                output, exit_status = cache[cache_key]
                f.write(f'<tr><td>{escape(name)}</td><td>{exit_status}</td><td>{escape(output)}</td></tr>')
            f.write('</table>')
    except IOError as e:
        print(f"Error: Unable to write to {report_path}: {e}")
        return

if __name__ == '__main__':
    main()

import sys
import json
import re
import operator
import ast

class SafeEval(ast.NodeVisitor):
    def __init__(self, allowed_names):
        self.allowed_names = allowed_names
        self.result = 0

    def visit_BinOp(self, node):
        self.visit(node.left)
        self.visit(node.right)
        if isinstance(node.op, ast.Add):
            self.result += node.right.n
        elif isinstance(node.op, ast.Sub):
            self.result -= node.right.n
        elif isinstance(node.op, ast.Mult):
            self.result *= node.right.n

    def visit_Num(self, node):
        self.result = node.n

    def visit_Name(self, node):
        if node.id in self.allowed_names:
            self.result = self.allowed_names[node.id]
        else:
            raise ValueError(f"Use of name '{node.id}' is not allowed")

    def visit_Expr(self, node):
        self.visit(node.value)

    def visit_Expression(self, node):
        self.visit(node.body)

    def generic_visit(self, node):
        raise ValueError(f"Unsupported operation: {ast.dump(node)}")

def evaluate_expression(expr, vars_dict):
    try:
        tree = ast.parse(expr, mode='eval')
        evaluator = SafeEval(vars_dict)
        evaluator.visit(tree)
        return evaluator.result
    except Exception as e:
        sys.stderr.write(f"error: {str(e)}\n")
        sys.exit(1)

def process_template(template, vars_dict):
    result = {}
    for key, value in template.items():
        if isinstance(value, str):
            match = re.fullmatch(r'{{(.*)}}', value)
            if match:
                expr = match.group(1)
                try:
                    computed_value = evaluate_expression(expr, vars_dict)
                    result[key] = computed_value
                    sys.stderr.write(f"placeholder: {{{expr}}} = {computed_value}\n")
                except Exception as e:
                    sys.stderr.write(f"error: {str(e)}\n")
                    sys.exit(1)
            else:
                result[key] = value
        else:
            result[key] = value
    return result

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("error: Incorrect number of arguments\n")
        sys.exit(1)

    template_file, vars_file = sys.argv[1], sys.argv[2]

    try:
        with open(template_file, 'r') as f:
            template = json.load(f)
        with open(vars_file, 'r') as f:
            vars_dict = json.load(f)
    except Exception as e:
        sys.stderr.write(f"error: {str(e)}\n")
        sys.exit(1)

    try:
        result = process_template(template, vars_dict)
        print(json.dumps(result, separators=(',', ':')))
    except Exception as e:
        sys.stderr.write(f"error: {str(e)}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import time
from pathlib import Path
import re

def validate_jobs_file(jobs_data):
    if not isinstance(jobs_data, dict) or 'vars' not in jobs_data or 'jobs' not in jobs_data:
        raise ValueError("Invalid JOBS_FILE format")
    if not isinstance(jobs_data['vars'], dict) or not isinstance(jobs_data['jobs'], list):
        raise ValueError("Invalid JOBS_FILE format")
    for job in jobs_data['jobs']:
        if not isinstance(job, dict) or 'id' not in job or 'expr' not in job:
            raise ValueError("Invalid job format in JOBS_FILE")
        if not isinstance(job['id'], str) or not isinstance(job['expr'], str):
            raise ValueError("Invalid job format in JOBS_FILE")

def validate_state_file(state):
    if not isinstance(state, list):
        raise ValueError("Invalid STATE_FILE format")
    for item in state:
        if not isinstance(item, str):
            raise ValueError("Invalid STATE_FILE format")

def sanitize_expression(expr):
    allowed_pattern = re.compile(r'^[a-zA-Z0-9_+\-*/%()\s]+$')
    if not allowed_pattern.match(expr):
        raise ValueError("Invalid characters in job expression")
    return expr

def safe_eval(expr, vars_dict):
    expr = sanitize_expression(expr)
    return eval(expr, {"__builtins__": {}}, vars_dict)

def main():
    if len(sys.argv) != 4:
        print("Usage: python run_jobs.py <JOBS_FILE> <STATE_FILE> <RATE>")
        sys.exit(1)

    jobs_file = sys.argv[1]
    state_file = sys.argv[2]
    rate = int(sys.argv[3])

    if rate <= 0:
        print("RATE must be a positive integer")
        sys.exit(1)

    try:
        with open(jobs_file, 'r') as f:
            jobs_data = json.load(f)
        validate_jobs_file(jobs_data)
    except (json.JSONDecodeError, ValueError, FileNotFoundError) as e:
        print(f"Error reading JOBS_FILE: {e}")
        sys.exit(1)

    vars_dict = jobs_data['vars']
    jobs = jobs_data['jobs']

    state = []
    try:
        if Path(state_file).exists():
            with open(state_file, 'r') as f:
                state = json.load(f)
            validate_state_file(state)
    except (json.JSONDecodeError, ValueError) as e:
        print(f"Error reading STATE_FILE: {e}")
        sys.exit(1)

    last_start_time = None

    for job in jobs:
        job_id = job['id']
        if job_id in state:
            continue

        if last_start_time is not None:
            elapsed = time.time() - last_start_time
            if elapsed < 1 / rate:
                time.sleep(1 / rate - elapsed)

        try:
            result = safe_eval(job['expr'], vars_dict)
            print(f"{job_id} {result}")
            sys.stdout.flush()

            state.append(job_id)
            with open(state_file, 'w') as f:
                json.dump(state, f)

            last_start_time = time.time()
        except Exception as e:
            print(f"Error processing job {job_id}: {e}")
            sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import time
import json
import os
import re
import ssl
from urllib.parse import urlparse
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def load_cache(cache_file):
    if os.path.exists(cache_file):
        with open(cache_file, 'r', encoding='utf-8') as f:
            try:
                cache = json.load(f)
                if isinstance(cache, dict) and all(isinstance(v, dict) and 'retrieved_at' in v and 'body' in v for v in cache.values()):
                    return cache
            except json.JSONDecodeError:
                pass
    return {}

def save_cache(cache, cache_file):
    with open(cache_file, 'w', encoding='utf-8') as f:
        json.dump(cache, f, ensure_ascii=False, indent=2)

def log_event(log_file, url, event, seconds):
    log_entry = json.dumps({"url": url, "event": event, "seconds": seconds})
    with open(log_file, 'a', encoding='utf-8') as f:
        f.write(log_entry + '\n')

def fetch_url(url):
    try:
        context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
        context.check_hostname = True
        context.verify_mode = ssl.CERT_REQUIRED
        request = Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urlopen(request, context=context) as response:
            return response.read().decode('utf-8')
    except (URLError, HTTPError, ssl.SSLError):
        return None

def main(urls_file, cache_file):
    if not os.path.isfile(urls_file) or not os.access(urls_file, os.R_OK):
        sys.exit("Error: Cannot read the URLs file.")
    if not os.access(os.path.dirname(cache_file), os.W_OK):
        sys.exit("Error: Cannot write to the cache file directory.")

    cache = load_cache(cache_file)
    log_file = os.path.join(os.path.dirname(cache_file), 'cacher.log')
    failed = False

    with open(urls_file, 'r', encoding='utf-8') as f:
        for line in f:
            url = line.rstrip()
            if not url or not is_valid_url(url):
                continue

            start_time = time.time()
            current_epoch_seconds = start_time

            if url in cache:
                cache_entry = cache[url]
                if current_epoch_seconds - cache_entry['retrieved_at'] < 300:
                    print(cache_entry['body'])
                    log_event(log_file, url, "cache_hit", current_epoch_seconds - start_time)
                    continue

            time.sleep(max(0.5 - (time.time() - start_time), 0))
            body = fetch_url(url)

            if body is None or not body.strip():
                log_event(log_file, url, "failed", current_epoch_seconds - start_time)
                failed = True
            else:
                print(body)
                cache[url] = {"retrieved_at": current_epoch_seconds, "body": body}
                log_event(log_file, url, "fetched", current_epoch_seconds - start_time)

            save_cache(cache, cache_file)

    sys.exit(1 if failed else 0)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("Usage: python cacher.py <urls_file> <cache_file>")
    main(sys.argv[1], sys.argv[2])

import os
