import sys
import time
import xml.etree.ElementTree as ET
import re
from xml.etree.ElementTree import ParseError

def is_token_valid(token_id, token):
    try:
        user, expiry = token.split('.')
        expiry = int(expiry)
    except ValueError:
        return False
    return user.strip() == token_id.strip() and expiry >= int(time.time())

def evaluate_condition(condition, user):
    try:
        # Use a restricted environment for eval
        allowed_names = {'user': user}
        # Use a safer eval by restricting the globals and locals
        return eval(condition, {"__builtins__": None}, allowed_names)
    except Exception:
        return False

def validate_xml_content(element):
    # Basic validation to prevent XXE and other attacks
    if element.tag not in ['policy', 'token-id', 'rule']:
        raise ValueError("Invalid XML structure")
    for child in element:
        validate_xml_content(child)

def main(policy_path, token, action):
    # Validate the policy_path to prevent directory traversal
    if not re.match(r'^[\w\-./]+$', policy_path):
        print('deny')
        return

    try:
        tree = ET.parse(policy_path)
        root = tree.getroot()
        validate_xml_content(root)
    except (ParseError, FileNotFoundError, ValueError):
        print('deny')
        return

    token_id = root.find('token-id').text
    if not is_token_valid(token_id, token):
        print('deny')
        return

    user, _ = token.split('.')
    user = user.strip()

    for rule in root.findall('rule'):
        if rule.get('action') == action:
            condition = rule.get('condition')
            if evaluate_condition(condition, user):
                print('allow')
                return

    print('deny')

