import sys
import json
import hmac
import hashlib
import ast
import os

def safe_eval(expr, env):
    """
    Safely evaluate an expression with limited allowed operations.
    """
    allowed_operations = (ast.Expression, ast.Call, ast.Name, ast.Load, ast.Compare,
                          ast.Gt, ast.Lt, ast.GtE, ast.LtE, ast.Eq, ast.NotEq,
                          ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow)

    def validate(node):
        if isinstance(node, allowed_operations):
            for child in ast.iter_child_nodes(node):
                validate(child)
        else:
            raise ValueError("Unsafe operation detected")

    tree = ast.parse(expr, mode='eval')
    validate(tree)
    return eval(compile(tree, '<string>', 'eval'), {}, env)

def main():
    if len(sys.argv) != 4:
        sys.exit(0)

    flags_path, token_path, key_path = sys.argv[1:]

    # Validate file paths
    if not os.path.isfile(flags_path) or not os.path.isfile(token_path) or not os.path.isfile(key_path):
        sys.exit(0)

    try:
        with open(token_path, 'r') as token_file:
            payload = token_file.readline().strip()
            signature = token_file.readline().strip()

        with open(key_path, 'rb') as key_file:
            key = key_file.read().strip()

        if not hmac.compare_digest(signature, hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()):
            sys.exit(0)

        payload_data = json.loads(payload)
        role = payload_data.get('role')
        attributes = payload_data.get('attributes', {})

        if not isinstance(attributes, dict):
            sys.exit(0)

        with open(flags_path, 'r') as flags_file:
            flags = json.load(flags_file)

        if not isinstance(flags, dict):
            sys.exit(0)

        for flag_name, flag_data in flags.items():
            if not isinstance(flag_data, dict) or 'role' not in flag_data or 'expr' not in flag_data:
                continue
            if flag_data['role'] == role:
                try:
                    result = safe_eval(flag_data['expr'], attributes)
                    print(f"{flag_name}: {result}")
                except Exception:
                    continue

    except (json.JSONDecodeError, ValueError, OSError, TypeError):
        sys.exit(0)

