import sys
import json
import time
import hmac
import hashlib
import base64
from datetime import datetime

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("ERROR\n")
        return

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (FileNotFoundError, json.JSONDecodeError):
        sys.stderr.write("ERROR\n")
        return

    secret = config.get("secret")
    api_key = config.get("api_key")
    role = config.get("role")

    if not all([secret, api_key, role]):
        sys.stderr.write("ERROR\n")
        return

    for line in sys.stdin:
        line = line.strip()
        if not line:
            sys.stderr.write("ERROR\n")
            continue

        parts = line.split()
        if len(parts) < 2:
            sys.stderr.write("ERROR\n")
            continue

        command = parts[0]
        if command == "issue":
            if len(parts) != 2:
                sys.stderr.write("ERROR\n")
                continue
            given_api_key = parts[1]
            if hmac.compare_digest(given_api_key, api_key):
                token = generate_token(secret, role)
                print(token)
            else:
                print("DENY")
                log_deny("issue")
        elif command == "check":
            if len(parts) != 3:
                sys.stderr.write("ERROR\n")
                continue
            token, given_role = parts[1], parts[2]
            if verify_token(secret, token, given_role):
                print("ALLOW")
            else:
                print("DENY")
                log_deny("check")
        else:
            sys.stderr.write("ERROR\n")

def generate_token(secret, role):
    timestamp = int(time.time())
    message = f"{role}-{timestamp}"
    signature = hmac.new(secret.encode(), message.encode(), hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(signature).decode().rstrip('=')
    return f"{message}.{token}"

def verify_token(secret, token, role):
    try:
        message, sig = token.rsplit('.', 1)
        if not message.startswith(f"{role}-"):
            return False
        expected_sig = hmac.new(secret.encode(), message.encode(), hashlib.sha256).digest()
        expected_sig_b64 = base64.urlsafe_b64encode(expected_sig).decode().rstrip('=')
        return hmac.compare_digest(sig, expected_sig_b64)
    except (ValueError, IndexError):
        return False

def log_deny(command):
    timestamp = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    with open("auth.log", "a") as log_file:
        log_file.write(f"{timestamp} {command}\n")

if __name__ == "__main__":
    main()

import sys
import time
import hashlib
import hmac
import base64
import os

def read_file(file_path):
    with open(file_path, 'r') as file:
        lines = file.readlines()
    secret = lines[0].strip()
    api_keys = {line.strip() for line in lines[1:]}
    return secret, api_keys

def generate_token(secret, api_key, resource):
    timestamp = int(time.time()) + 60
    data = f"{api_key}:{resource}:{timestamp}"
    hmac_digest = hmac.new(secret.encode(), data.encode(), hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(hmac_digest + data.encode()).decode()
    return token

def validate_token(secret, token, resource):
    try:
        decoded = base64.urlsafe_b64decode(token.encode())
        hmac_digest, data = decoded[:32], decoded[32:]
        api_key, res, timestamp = data.decode().split(':')
        if int(timestamp) < int(time.time()):
            return "DENY expired"
        if res != resource:
            return "DENY wrong_resource"
        expected_hmac = hmac.new(secret.encode(), data, hashlib.sha256).digest()
        if not hmac.compare_digest(hmac_digest, expected_hmac):
            return "DENY invalid_token"
        return "ALLOW"
    except Exception:
        return "DENY invalid_token"

def main():
    if len(sys.argv) != 2:
        print("Usage: python token_service.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    secret, api_keys = read_file(file_path)
    token_count = 0

    for line in sys.stdin:
        command = line.strip().split()
        if not command:
            continue

        if command[0] == "issue":
            if len(command) != 3:
                print("Invalid command format")
                continue

            api_key, resource = command[1], command[2]
            if api_key not in api_keys:
                print("DENY invalid_key")
            elif token_count >= 5:
                print("DENY rate_limited")
            else:
                token = generate_token(secret, api_key, resource)
                print(f"TOKEN {token}")
                token_count += 1

        elif command[0] == "validate":
            if len(command) != 3:
                print("Invalid command format")
                continue

            token, resource = command[1], command[2]
            print(validate_token(secret, token, resource))

        else:
            print("Invalid command")

if __name__ == "__main__":
    main()

