import sys
import os
import json
import xml.etree.ElementTree as ET
from cryptography.fernet import Fernet
import base64
import hashlib
import hmac
import secrets

def generate_key(passphrase):
    # Use a secure method to generate a key from the passphrase
    return base64.urlsafe_b64encode(hashlib.sha256(passphrase.encode()).digest())

def encrypt(text, passphrase):
    key = generate_key(passphrase)
    f = Fernet(key)
    return f.encrypt(text.encode()).decode()

def decrypt(encrypted_text, passphrase):
    key = generate_key(passphrase)
    f = Fernet(key)
    try:
        return f.decrypt(encrypted_text.encode()).decode()
    except Exception as e:
        print(f"Decryption error: {e}")
        sys.exit(1)

def safe_eval(expr, allowed_globals=None, allowed_locals=None):
    # Restrict the eval environment to a safe subset
    if allowed_globals is None:
        allowed_globals = {"__builtins__": {}}
    if allowed_locals is None:
        allowed_locals = {}
    return eval(expr, allowed_globals, allowed_locals)

def main():
    if len(sys.argv) < 2:
        print("Usage: python confgen.py <encrypt|render> [config.xml]")
        sys.exit(1)

    command = sys.argv[1]
    passphrase = os.environ.get('CONFIG_PASSPHRASE')

    if not passphrase:
        print("Error: CONFIG_PASSPHRASE environment variable not set")
        sys.exit(1)

    if command == 'encrypt':
        text = sys.stdin.read()
        encrypted = encrypt(text, passphrase)
        print(encrypted)

    elif command == 'render':
        if len(sys.argv) != 3:
            print("Usage: python confgen.py render config.xml")
            sys.exit(1)

        config_file = sys.argv[2]
        try:
            tree = ET.parse(config_file)
            root = tree.getroot()
        except ET.ParseError as e:
            print(f"XML parsing error: {e}")
            sys.exit(1)

        if root.tag != 'configuration':
            print("Error: Root element must be <configuration>")
            sys.exit(1)

        config = {}
        for setting in root.findall('setting'):
            name = setting.get('name')
            encrypted_value = setting.text.strip()
            decrypted_value = decrypt(encrypted_value, passphrase)

            if decrypted_value == '{{expr}}':
                expr = input(f"Enter value for {name}: ")
                try:
                    config[name] = safe_eval(expr)
                except Exception as e:
                    print(f"Error evaluating expression for {name}: {e}")
                    sys.exit(1)
            else:
                config[name] = decrypted_value

        print(json.dumps(config))

    else:
        print(f"Unknown command: {command}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from xml.etree.ElementTree import ParseError
from xml.parsers.expat import ExpatError

def read_config(file_path):
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
        max_workers = int(root.attrib['max_workers'])
        min_interval_ms = int(root.attrib['min_interval_ms'])
        salt = root.attrib['salt']

        if max_workers <= 0 or min_interval_ms < 0:
            raise ValueError("Invalid configuration values")

        return max_workers, min_interval_ms, salt
    except (ParseError, ExpatError, ValueError, KeyError) as e:
        sys.exit(f"Error reading config: {e}")

def compute_fingerprint(file_path, salt):
    try:
        if not os.path.isfile(file_path):
            return file_path + '\tERROR'

        with open(file_path, 'rb') as f:
            file_bytes = f.read()
        salted_bytes = (salt + file_bytes).encode('utf-8')
        digest = hashlib.sha256(salted_bytes).hexdigest()
        return file_path + '\t' + digest
    except OSError:
        return file_path + '\tERROR'

def process_paths(paths, max_workers, min_interval_ms, salt):
    results = []
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = []
        last_submission_time = time.monotonic()

        for path in paths:
            current_time = time.monotonic()
            elapsed_time = (current_time - last_submission_time) * 1000
            if elapsed_time < min_interval_ms:
                time.sleep((min_interval_ms - elapsed_time) / 1000)
            futures.append(executor.submit(compute_fingerprint, path, salt))
            last_submission_time = time.monotonic()

        for future in as_completed(futures):
            results.append(future.result())

    return results

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: python fingerprint_batch.py <config.xml>")

    config_file = sys.argv[1]
    max_workers, min_interval_ms, salt = read_config(config_file)

    try:
        paths = sys.stdin.read().strip().split('\n')
    except Exception as e:
        sys.exit(f"Error reading input paths: {e}")

    results = process_paths(paths, max_workers, min_interval_ms, salt)
    for result in results:
        print(result)

if __name__ == '__main__':
    main()

import sys
import xml.etree.ElementTree as ET
import json
import re
import ast
import operator

class ExpressionEvaluator:
    def __init__(self):
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.USub: operator.neg
        }

    def eval_expr(self, expr, values):
        try:
            tree = ast.parse(expr, mode='eval')
            return self._eval(tree.body, values)
        except (SyntaxError, TypeError, ZeroDivisionError):
            return None

    def _eval(self, node, values):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._eval(node.left, values)
            right = self._eval(node.right, values)
            if left is None or right is None:
                return None
            return self.operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = self._eval(node.operand, values)
            if operand is None:
                return None
            return self.operators[type(node.op)](operand)
        elif isinstance(node, ast.Name):
            return values.get(node.id)
        else:
            return None

def sanitize_name(name):
    return re.sub(r'[^a-zA-Z0-9_]', '', name)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError:
        sys.exit(1)

    values = {}
    recorded = False
    evaluator = ExpressionEvaluator()

    for field in root.findall('field'):
        name = sanitize_name(field.get('name'))
        expr = field.get('expr')
        value = evaluator.eval_expr(expr, values)

        if value is not None:
            values[name] = value
            recorded = True
            print(f"INFO {name} {value}", file=sys.stderr)
        else:
            print(f"ERROR {name}", file=sys.stderr)

    if recorded:
        print(json.dumps(values))
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor
import re
import ast
import operator

class SafeEvaluator:
    def __init__(self):
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.Pow: operator.pow,
            ast.BitXor: operator.xor,
            ast.USub: operator.neg
        }

    def eval_expr(self, expr, context):
        try:
            tree = ast.parse(expr, mode='eval')
            return self._eval(tree.body, context)
        except Exception:
            return ''

    def _eval(self, node, context):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._eval(node.left, context)
            right = self._eval(node.right, context)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = self._eval(node.operand, context)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](operand)
        elif isinstance(node, ast.Name):
            if node.id in context:
                return context[node.id]
        raise ValueError("Unsupported operation")

def evaluate_expression(expr, w, h):
    evaluator = SafeEvaluator()
    return evaluator.eval_expr(expr, {'w': w, 'h': h})

def process_line(line, expr):
    match = re.match(r'w=(\d+) h=(\d+)', line)
    if match:
        w, h = map(int, match.groups())
        if w < 0 or h < 0:
            return ''
        return str(evaluate_expression(expr, w, h))
    return ''

def main():
    if len(sys.argv) != 2:
        print("Usage: python transform.py <config_file>", file=sys.stderr)
        sys.exit(1)

    config_file = sys.argv[1]
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        max_concurrency = int(root.get('max-concurrency'))
        expr = root.find('expr').text
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    with ThreadPoolExecutor(max_workers=max_concurrency) as executor:
        futures = []
        for line in sys.stdin:
            future = executor.submit(process_line, line.strip(), expr)
            futures.append(future)

        for future in futures:
            result = future.result()
            if result:
                print(result)

if __name__ == "__main__":
    main()

import sys
import os
import json
import hashlib
import hmac
import re

def render_report(input_file, output_file):
    try:
        with open(input_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except (json.JSONDecodeError, FileNotFoundError, IOError) as e:
        print(f"Error reading input file: {e}")
        sys.exit(1)

    if not isinstance(data, dict) or 'title' not in data or 'vars' not in data or 'blocks' not in data:
        print("Invalid input format")
        sys.exit(1)

    title = data['title']
    vars = data['vars']
    blocks = data['blocks']

    if not isinstance(title, str) or not isinstance(vars, dict) or not isinstance(blocks, list):
        print("Invalid data types in input")
        sys.exit(1)

    rendered_blocks = []
    pattern = re.compile(r'\{\{(.*?)\}\}')

    for block in blocks:
        if not isinstance(block, str):
            print("Invalid block type")
            sys.exit(1)

        def replace_expr(match):
            expr = match.group(1).strip()
            try:
                # Use a restricted eval environment
                allowed_names = {k: v for k, v in vars.items() if isinstance(v, (int, float, str))}
                value = eval(expr, {"__builtins__": None}, allowed_names)
                return str(value)
            except Exception as e:
                print(f"Error evaluating expression '{expr}': {e}")
                return match.group(0)

        block = pattern.sub(replace_expr, block)
        rendered_blocks.append(block)

    try:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write('<!DOCTYPE html>\n')
            f.write(f'<html><head><title>{title}</title></head><body>\n')
            f.write(f'<h1>{title}</h1>\n')
            for block in rendered_blocks:
                f.write(f'{block}\n')
            f.write('</body></html>\n')
    except IOError as e:
        print(f"Error writing output file: {e}")
        sys.exit(1)

def generate_tag(output_file):
    key_file = os.environ.get('REPORT_KEY_FILE')
    if not key_file:
        print("REPORT_KEY_FILE environment variable is not set")
        sys.exit(1)

    try:
        with open(key_file, 'rb') as f:
            key = f.read()
    except IOError as e:
        print(f"Error reading key file: {e}")
        sys.exit(1)

    try:
        with open(output_file, 'rb') as f:
            content = f.read()
    except IOError as e:
        print(f"Error reading output file: {e}")
        sys.exit(1)

    tag = hmac.new(key, content, hashlib.sha256).hexdigest()

    tag_file = f"{output_file}.tag"
    try:
        with open(tag_file, 'w', encoding='utf-8') as f:
            f.write(tag)
    except IOError as e:
        print(f"Error writing tag file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render_report.py <input.json> <output.html>")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    render_report(input_file, output_file)
    generate_tag(output_file)

import sys
import argparse
import hashlib
import html
import os

def process_records(records_file):
    purchases = []
    with open(records_file, 'r') as file:
        for line_number, line in enumerate(file, start=1):
            line = line.strip()
            if not line:
                continue
            parts = line.split(',')
            if len(parts) == 3 and parts[0] and parts[1].isdigit() and parts[2].isdigit():
                name, qty, price_cents = parts
                purchases.append((name, int(qty), int(price_cents)))
                print(f"INFO {name} {qty}", file=sys.stderr)
            else:
                print(f"ERROR line {line_number}", file=sys.stderr)
    return purchases

def compute_signature(key, purchases):
    key_bytes = key.encode('utf-8')
    signature = hashlib.sha256(key_bytes)
    for name, qty, price_cents in purchases:
        signature.update(f"{name},{qty},{price_cents}".encode('utf-8'))
    return signature.hexdigest()

def write_receipt_html(out_file, purchases, signature):
    with open(out_file, 'w') as file:
        file.write("<table>\n")
        for name, qty, price_cents in purchases:
            total_price = (qty * price_cents) / 100
            file.write(f"  <tr><td>{html.escape(name)}</td><td>{qty}</td><td>{total_price:.2f}</td></tr>\n")
        file.write("</table>\n")
        file.write(f"<p>Signature: <code>{signature}</code></p>\n")

def validate_file_path(file_path):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")
    if not os.access(file_path, os.R_OK):
        raise PermissionError(f"File is not readable: {file_path}")

def main():
    parser = argparse.ArgumentParser(description='Process purchase records and generate a receipt.')
    parser.add_argument('--records', required=True, help='File containing purchase records')
    parser.add_argument('--key', required=True, help='File containing the key for signature generation')
    parser.add_argument('--out', required=True, help='Output HTML file for the receipt')
    args = parser.parse_args()

    try:
        validate_file_path(args.records)
        validate_file_path(args.key)
    except (FileNotFoundError, PermissionError) as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        purchases = process_records(args.records)
        with open(args.key, 'r') as key_file:
            key = key_file.read().strip()
        signature = compute_signature(key, purchases)
        write_receipt_html(args.out, purchases, signature)
    except Exception as e:
        print(f"Error processing files: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import csv
import time
import os
import secrets
import re

def generate_nonce():
    return secrets.token_hex(16)

def render_template(template, id, title, nonce):
    return template.replace('{{id}}', id).replace('{{title}}', title).replace('{{nonce}}', nonce)

def validate_id(id):
    return re.match(r'^[A-Za-z0-9_-]+$', id) is not None

def main():
    if len(sys.argv) != 4:
        print("Usage: python render_pages.py <template_file> <csv_file> <output_dir>")
        sys.exit(1)

    template_file, csv_file, output_dir = sys.argv[1:]

    if not os.path.isdir(output_dir):
        print(f"Error: {output_dir} is not a valid directory.")
        sys.exit(1)

    try:
        with open(template_file, 'r', encoding='utf-8') as f:
            template = f.read()
    except FileNotFoundError:
        print(f"Error: Template file {template_file} not found.")
        sys.exit(1)
    except IOError:
        print(f"Error: Unable to read template file {template_file}.")
        sys.exit(1)

    try:
        with open(csv_file, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if 'id' not in reader.fieldnames or 'title' not in reader.fieldnames:
                print("Error: CSV file must contain 'id' and 'title' columns.")
                sys.exit(1)

            for row in reader:
                id = row['id']
                title = row['title']

                if not validate_id(id):
                    print(f"Error: Invalid id '{id}' in CSV file.")
                    continue

                nonce = generate_nonce()

                output_path = os.path.join(output_dir, f"{id}.html")
                try:
                    with open(output_path, 'w', encoding='utf-8') as f:
                        f.write(render_template(template, id, title, nonce))
                    print(output_path)
                except IOError:
                    print(f"Error: Unable to write to output file {output_path}.")

                time.sleep(0.1)

    except FileNotFoundError:
        print(f"Error: CSV file {csv_file} not found.")
        sys.exit(1)
    except IOError:
        print(f"Error: Unable to read CSV file {csv_file}.")
        sys.exit(1)

    sys.exit(0)

