    main()

import sys
import os
import hashlib
import ast
import signal

class TimeoutException(Exception):
    pass

def timeout_handler(signum, frame):
    raise TimeoutException

def safe_eval(node, namespace):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body, namespace)
    elif isinstance(node, ast.Name):
        if node.id in namespace:
            return namespace[node.id]
        else:
            raise NameError(f"name '{node.id}' is not defined")
    elif isinstance(node, ast.Load):
        return safe_eval(node.value, namespace)
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left, namespace)
        right = safe_eval(node.right, namespace)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.UnaryOp):
        operand = safe_eval(node.operand, namespace)
        if isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.USub):
            return -operand
    elif isinstance(node, ast.Call):
        func = safe_eval(node.func, namespace)
        args = [safe_eval(arg, namespace) for arg in node.args]
        return func(*args)
    else:
        raise ValueError(f"Unsupported operation: {ast.dump(node)}")

def main():
    input_data = sys.stdin.buffer.read()
    first_newline = input_data.find(b'\n')
    if first_newline == -1:
        sys.stderr.write("ERROR: Invalid input format\n")
        sys.exit(1)

    header = input_data[:first_newline].decode('utf-8')
    if not header.startswith('check='):
        sys.stderr.write("ERROR: Invalid input format\n")
        sys.exit(1)

    expected_check = header[6:]
    body = input_data[first_newline + 1:]

    salt = os.getenv('RECIPE_SALT', '')
    if not salt:
        sys.stderr.write("ERROR: RECIPE_SALT environment variable not set\n")
        sys.exit(1)

    computed_check = hashlib.sha256(body + salt.encode('utf-8')).hexdigest()
    if computed_check != expected_check:
        sys.stderr.write("ERROR: check mismatch\n")
        sys.exit(1)

    lines = body.decode('utf-8').splitlines()
    namespace = {}

    for i, line in enumerate(lines, start=1):
        line = line.strip()
        if not line:
            continue

        if '=' not in line:
            sys.stderr.write(f"ERROR line {i}: Invalid assignment\n")
            sys.exit(1)

        name, expression = line.split('=', 1)
        name = name.strip()
        expression = expression.strip()

        if not name.isidentifier():
            sys.stderr.write(f"ERROR line {i}: Invalid variable name\n")
            sys.exit(1)

        try:
            tree = ast.parse(expression, mode='eval')
            signal.signal(signal.SIGALRM, timeout_handler)
            signal.alarm(1)  # 1 second timeout
            value = safe_eval(tree.body, namespace)
            signal.alarm(0)
            print(f"{name}={value}")
            sys.stderr.write(f"OK {name}={value}\n")
            namespace[name] = value
        except TimeoutException:
            sys.stderr.write(f"ERROR line {i}: Evaluation timed out\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"ERROR line {i}: {str(e)}\n")
            sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import time
import hashlib
from collections import deque
import re

def compute_key(expression):
    return hashlib.sha256(expression.encode('utf-8')).hexdigest()

def evaluate_expression(expression):
    try:
        # Use a safe eval by restricting the allowed functions and operators
        allowed_names = {
            '__builtins__': None,
        }
        result = eval(expression, {"__builtins__": None}, allowed_names)
        return int(result)
    except ZeroDivisionError:
        return 0
    except Exception:
        return None

def validate_expression(expression):
    # Validate that the expression contains only allowed characters
    if not re.match(r'^[\d\s\(\)\+\-\*/]+$', expression):
        return False
    return True

def read_cache(cache_path):
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                key, value = line.strip().split(' ', 1)
                cache[key] = int(value)
    return cache

def write_cache(cache_path, cache):
    with open(cache_path, 'w') as f:
        for key, value in cache.items():
            f.write(f"{key} {value}\n")

def main(input_path, output_path):
    cache_path = os.path.join(os.getcwd(), 'expr.cache')
    cache = read_cache(cache_path)
    results = []
    uncached_queue = deque()
    current_time = time.time()

    try:
        with open(input_path, 'r') as infile:
            for expression in infile:
                expression = expression.strip()
                if not validate_expression(expression):
                    results.append(None)
                    continue

                key = compute_key(expression)
                if key in cache:
                    results.append(cache[key])
                else:
                    while (uncached_queue and 
                           current_time - uncached_queue[0] >= 1 and 
                           len(uncached_queue) >= 5):
                        time.sleep(0.1)
                    uncached_queue.append(time.time())
                    result = evaluate_expression(expression)
                    if result is not None:
                        cache[key] = result
                        results.append(result)
                    else:
                        results.append(None)

        write_cache(cache_path, cache)

        with open(output_path, 'w') as outfile:
            for result in results:
                if result is not None:
                    outfile.write(f"{result}\n")
                else:
                    outfile.write("Invalid expression\n")

    except IOError as e:
        print(f"Error handling files: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python evalcache.py <input_path> <output_path>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

import sys
