def log_message(message):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_path = os.path.abspath('render.log')
    try:
        with open(log_path, 'a', encoding='utf-8') as log_file:
            log_file.write(f"{timestamp} {message}\n")
    except Exception as e:
        print(f"ERROR: Could not write to log file: {str(e)}", file=sys.stderr)
        sys.exit(1)

def safe_eval(expr, values):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expr, mode='eval')
        # Compile the AST into a code object
        code = compile(tree, filename="<ast>", mode="eval")
        # Evaluate the code object with the provided values
        return eval(code, {"__builtins__": {}}, values)
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {str(e)}")

def render_template(template, values):
    def replace_placeholder(match):
        expr = match.group(1)
        try:
            result = safe_eval(expr, values)
            return f"{result:.2f}"
        except ValueError as e:
            raise ValueError(f"Invalid expression: {str(e)}")

    return re.sub(r'\{\{(.*?)\}\}', replace_placeholder, template)

def main():
