    try:
        values_path = os.path.abspath(values_path)
        with open(values_path, 'r', encoding='utf-8') as values_file:
            values = json.load(values_file)
    except Exception as e:
        log_message(f"ERROR Could not read values file: {str(e)}")
        sys.exit(1)

    if not isinstance(values, dict) or not all(isinstance(v, (int, float)) for v in values.values()):
        log_message("ERROR VALUES_PATH is not a JSON object with numeric values")
        sys.exit(1)

    try:
        rendered_html = render_template(template, values)
        print(rendered_html)
        log_message(f"INFO rendered {template_path}")
    except ValueError as e:
