import json
import time
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
import ast

def evaluate_expression(expression, data):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')
        # Compile the AST into a code object
        code = compile(tree, filename="<ast>", mode="eval")
        # Evaluate the code object with the provided data as the local namespace
        return str(eval(code, {}, data))
    except Exception:
        return ''

def render_template(template, data):
    pattern = r'\{\{(.+?)\}\}'
    matches = re.findall(pattern, template)
    rendered = template
    for match in matches:
        rendered = rendered.replace(f'{{{{ {match} }}}}', evaluate_expression(match, data))
    return rendered

def process_object(obj, template):
    time.sleep(0.2)
    return render_template(template, obj)

def main():
    try:
        with open('template.html', 'r', encoding='utf-8') as f:
            template = f.read()
    except FileNotFoundError:
        print("Error: template.html file not found.")
        return
    except Exception as e:
        print(f"Error reading template.html: {e}")
        return

