    rendered_strings = []
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for obj in data_array:
            if not isinstance(obj, dict):
                print("Error: Each item in data.json must be a JSON object.")
                return
            future = executor.submit(process_object, obj, template)
            futures.append(future)

        for future in as_completed(futures):
            rendered_strings.append(future.result())

    try:
