import sys
import subprocess
import concurrent.futures
import html
import re
import os

def is_valid_hostname(hostname):
    if len(hostname) > 255:
        return False
    if hostname[-1] == ".":
        hostname = hostname[:-1]
    allowed = re.compile(r"(?!-)[A-Z\d-]{1,63}(?<!-)$", re.IGNORECASE)
    return all(allowed.match(x) for x in hostname.split("."))

def ping_hostname(hostname):
    if not is_valid_hostname(hostname):
        return hostname, 'FAILED', 'Invalid hostname'
    try:
        result = subprocess.run(['ping', '-c', '1', hostname], capture_output=True, text=True, check=True)
        status = 'OK'
        output = result.stdout
    except subprocess.CalledProcessError as e:
        status = 'FAILED'
        output = e.stdout or e.stderr
    except Exception as e:
        status = 'FAILED'
        output = str(e)
    return hostname, status, output

def main():
    hostnames = [line.strip() for line in sys.stdin if line.strip()]
    if not hostnames:
        print("Error: No hostnames provided", file=sys.stderr)
        sys.exit(1)

    results = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
        future_to_hostname = {executor.submit(ping_hostname, hostname): hostname for hostname in hostnames}
        for future in concurrent.futures.as_completed(future_to_hostname):
            results.append(future.result())

    try:
        with open('report.html', 'w') as report_file:
            report_file.write('<table border="1">\n')
            report_file.write('<tr><th>Host</th><th>Status</th><th>Output</th></tr>\n')
            for hostname, status, output in results:
                report_file.write(f'<tr><td>{html.escape(hostname)}</td><td>{status}</td><td>{html.escape(output)}</td></tr>\n')
            report_file.write('</table>\n')
    except IOError as e:
        print(f"Error: Unable to write to report.html: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open('run.log', 'w') as log_file:
            for hostname, status, _ in results:
                log_file.write(f'{hostname} {status}\n')
    except IOError as e:
        print(f"Error: Unable to write to run.log: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
